mod slice_x2_probe {
    //! Instrumentation: count how often the host-loop
    //! `execute_with_inputs` falls back to the dispatch-loop branch for
    //! cross-loop JUMP exits.  In-code `closing_jump` work will keep
    //! shrinking this counter until the branch can be deleted.
    use std::sync::atomic::{AtomicUsize, Ordering};

    pub static EXECUTE_WITH_INPUTS_HITS: AtomicUsize = AtomicUsize::new(0);

    pub fn record_execute_with_inputs_hit() {
        EXECUTE_WITH_INPUTS_HITS.fetch_add(1, Ordering::Relaxed);
    }

    struct ReporterGuard;

    impl Drop for ReporterGuard {
        fn drop(&mut self) {
            if std::env::var_os("MAJIT_X2_PROBE").is_some() {
                eprintln!(
                    "[X2-PROBE] execute_with_inputs.external_jump={}",
                    EXECUTE_WITH_INPUTS_HITS.load(Ordering::Relaxed),
                );
            }
        }
    }

    thread_local! {
        static REPORTER: ReporterGuard = const { ReporterGuard };
    }

    pub fn arm_reporter() {
        REPORTER.with(|_| {});
    }
}

/// `have_debug_prints` — true only inside a debug section the `MAJIT_LOG`
/// prefix filter accepts, so a category filter silences these sites.
///
/// `debug_print.h` `OP_HAVE_DEBUG_PRINTS(r)` inlines one load of
/// `pypy_have_debug_prints`.
#[inline(always)]
fn majit_log_enabled() -> bool {
    majit_ir::debug::have_debug_prints()
}

/// The three flags a compiled entry reads, resolved together.
#[derive(Clone, Copy)]
struct EntryFlags {
    log_enabled: bool,
    debug_prints: bool,
    verify_enabled: bool,
}

/// The two log gates follow this thread's open debug section, so they are
/// read on every entry; a disabled log answers them without touching the
/// section state.
#[inline]
fn entry_flags() -> EntryFlags {
    EntryFlags {
        log_enabled: majit_log_enabled(),
        debug_prints: majit_ir::debug::have_debug_prints(),
        verify_enabled: majit_verify_enabled(),
    }
}

/// Whether `MAJIT_VERIFY` is set, cached at first access.
fn majit_verify_enabled() -> bool {
    static ENABLED: std::sync::LazyLock<bool> =
        std::sync::LazyLock::new(|| std::env::var_os("MAJIT_VERIFY").is_some());
    *ENABLED
}

/// Logging and dump gates, read once per process. The raw DONE_REF
/// entry falls back to the general path when any of these is on.
#[inline]
fn exec_diag_enabled() -> bool {
    static ENABLED: std::sync::LazyLock<bool> = std::sync::LazyLock::new(|| {
        majit_dump_enabled() || majit_verify_enabled() || majit_ir::debug::have_debug_prints()
    });
    *ENABLED
}

/// Whether `MAJIT_DUMP` is set, cached at first access.
fn majit_dump_enabled() -> bool {
    static ENABLED: std::sync::LazyLock<bool> =
        std::sync::LazyLock::new(|| std::env::var_os("MAJIT_DUMP").is_some());
    *ENABLED
}

