struct GcRootSlotGuard {
    slots: Vec<*mut GcRef>,
    registered: bool,
}

impl GcRootSlotGuard {
    #[expect(
        dead_code,
        reason = "constructor is paired with GcRootSlotGuard's retained RAII path"
    )]
    fn new(slots: Vec<*mut GcRef>) -> Self {
        if slots.is_empty() {
            return Self {
                slots,
                registered: false,
            };
        }
        let registered = with_cranelift_gc(|gc| {
            for &slot in &slots {
                unsafe {
                    gc.add_root(slot);
                }
            }
        })
        .is_some();
        Self { slots, registered }
    }
}

impl Drop for GcRootSlotGuard {
    fn drop(&mut self) {
        if !self.registered {
            return;
        }
        with_cranelift_gc(|gc| {
            for &slot in &self.slots {
                gc.remove_root(slot);
            }
        });
    }
}

fn write_barrier_if_managed(obj: GcRef) {
    if obj.is_null() {
        return;
    }
    with_cranelift_gc(|gc| {
        if gc.is_managed_heap_object(obj.0) {
            gc.write_barrier(obj);
        }
    });
}

thread_local! {
    /// Per-thread caller->callee result-kind expectations, keyed by the
    /// callee's `JitCellToken::identity_key`.
    static CALL_ASSEMBLER_EXPECTATIONS: RefCell<IndexMap<usize, IndexMap<CallAssemblerCallerId, u64>>> =
        RefCell::new(IndexMap::new());
    /// Thread-local deadframe storage for call_assembler results.
    /// Each test thread gets its own isolated registry, preventing
    /// non-deterministic failures from shared global state.
    static CALL_ASSEMBLER_DEADFRAMES: RefCell<IndexMap<u64, DeadFrame>> = RefCell::new(IndexMap::new());
    static NEXT_CALL_ASSEMBLER_DEADFRAME_HANDLE: Cell<u64> = const { Cell::new(1) };
}

const CALL_ASSEMBLER_OUTCOME_FINISH: i64 = 0;
const CALL_ASSEMBLER_OUTCOME_DEADFRAME: i64 = 1;

/// Callback to "force" a callee frame through the interpreter when
/// call_assembler hits a guard failure.  The callback takes the
/// callee frame pointer (from fail_args[0]) and runs the interpreter
/// to completion, returning the result as an i64.
static CALL_ASSEMBLER_FORCE_FN: OnceLock<extern "C" fn(i64) -> i64> = OnceLock::new();

/// `compile.py resume_in_blackhole(descr, deadframe)` parity:
/// callback to resume execution from the guard failure point using the
/// blackhole interpreter.  Args: `(descr_addr, deadframe)` →
/// `Option<result>`.  The receiver recovers the failed descr from
/// `descr_addr` via `Backend::fail_descr_arc_from_addr`
/// (`history.py` `cpu.get_latest_descr`) and derives
/// green_key / trace_id / fail_index from the descr identity
/// (`descr_owning_jct`).  No surrogate triple crosses the C-ABI.
/// The pending exception stays in `jf_guard_exc`; the receiver reads it
/// with `cpu.grab_exc_value` (`llmodel.py`).
type CallAssemblerBlackholeFn = fn(usize, *mut majit_backend::jitframe::JitFrame) -> Option<i64>;
static CALL_ASSEMBLER_BLACKHOLE_FN: OnceLock<CallAssemblerBlackholeFn> = OnceLock::new();

/// Register a blackhole callback for call_assembler guard failure resume.
/// The receiver reads `jf_guard_exc` (`cpu.grab_exc_value`, llmodel.py)
/// to seed `_prepare_resume_from_failure` (blackhole.py).
pub fn register_call_assembler_blackhole(f: CallAssemblerBlackholeFn) {
    let _ = CALL_ASSEMBLER_BLACKHOLE_FN.set(f);
}

/// compile.py handle_fail callback for call_assembler guard failures.
/// (raw_values_ptr, num_values, descr_addr) -> bridge_compiled.
///
/// `pyjitpl.py handle_guard_failure(self, resumedescr, deadframe)`
/// receives the descr directly; the C-ABI delivers the same shape via
/// `descr_addr` (recovered to `Arc<dyn FailDescr>` by the receiver)
/// instead of a surrogate `(green_key, trace_id, fail_index)` triple.
static CALL_ASSEMBLER_BRIDGE_FN: OnceLock<
    fn(*mut majit_backend::jitframe::JitFrame, usize, i64, bool) -> Option<i64>,
> = OnceLock::new();

/// On-demand resume callback: pyre-jit registers this to
/// drive `ResumeDataDirectReader` from the failed descr's `rd_numb` /
/// `rd_consts` / `rd_virtuals` / `rd_pendingfields`.  Mirrors PyPy's
/// `pyjitpl.py MetaInterp.rebuild_state_after_failure(resumedescr,
/// deadframe)` and the `resume.py blackhole_from_resumedata` flow
/// where the metainterp drives the decoder and the backend just
/// delivers the deadframe.
///
/// Args: `(descr_addr, outputs, types, bridge_num_inputs) -> bool`.
/// Returns `true` when the on-demand decode handled the descr (in
/// which case `*outputs` has been replaced with the rebuilt vec).
/// Returns `false` for synthetic FINISH / external-JUMP / Done* descrs
/// without a downcastable `ResumeGuardDescr`.
type ResumeDataDeoptFn = fn(usize, &mut Vec<i64>, &[Type], usize) -> bool;
static RESUMEDATA_DEOPT_FN: OnceLock<ResumeDataDeoptFn> = OnceLock::new();

/// Register the on-demand resume callback for cranelift deopt
/// materialisation.  pyre-jit calls this during JIT
/// boot alongside `register_call_assembler_blackhole`.
pub fn register_resumedata_deopt(f: ResumeDataDeoptFn) {
    let _ = RESUMEDATA_DEOPT_FN.set(f);
}

/// Dispatch entry used by the four runtime-deopt callers
/// (compiler.rs) — drives the on-demand
/// `ResumeDataDirectReader` callback
/// (`cranelift_resumedata_deopt`) which materialises virtuals + replays
/// pending fields straight from `rd_numb` / `rd_consts` / `rd_virtuals`
/// / `rd_pendingfields`, matching `pyjitpl.py rebuild_state_after_failure
/// MetaInterp.rebuild_state_after_failure(resumedescr, deadframe)` +
/// `resume.py blackhole_from_resumedata`.  No recovery_layout
/// walker fallback — production code paths always reach a
/// `ResumeGuardDescr` meta_descr with populated `rd_numb`.
///
/// When the callback returns false the descr has neither a
/// `ResumeGuardDescr` meta nor a populated `rd_numb`, which in the
/// current cranelift pipeline only happens for synthetic descrs that
/// never have a bridge attached and therefore never reach this
/// dispatch helper at runtime.  Falling through here panics loudly
/// instead of silently producing stale outputs — fixing the producer
/// (synthesise the meta + populate rd_numb) is the right response,
/// not reviving a backend-local cache.
fn rebuild_state_after_failure_dispatch(
    fail_descr: &DescrRef,
    outputs: &mut Vec<i64>,
    fail_arg_types: &[Type],
    bridge_num_inputs: usize,
) {
    let cb = RESUMEDATA_DEOPT_FN.get().copied().expect(
        "RESUMEDATA_DEOPT_FN not registered — the runtime must call \
         register_resumedata_deopt before any guard can fail.",
    );
    // `cranelift_resumedata_deopt` recovers the descr via
    // `Backend::fail_descr_arc_from_addr` → `recover_fail_descr_cell`,
    // which requires a `FailDescrCell` thin pointer.  Wrap in a fresh
    // cell and bake its address; the cell stays alive through the
    // callback, and the recovery bumps the refcount.
    let cell = majit_ir::FailDescrCell::wrap(fail_descr.clone());
    let descr_addr = majit_ir::FailDescrCell::thin_ptr(&cell);
    let _ = (fail_arg_types, bridge_num_inputs); // walker path removed
    let ok = cb(descr_addr, outputs, fail_arg_types, bridge_num_inputs);
    drop(cell);
    if !ok {
        let fd = as_fd(fail_descr);
        panic!(
            "cranelift_resumedata_deopt callback returned false for a runtime guard \
             failure — descr's meta_descr is not a ResumeGuardDescr or rd_numb is empty. \
             trace_id={} fail_index_per_trace={} fail_arg_types_len={}",
            fd.trace_id(),
            fd.fail_index_per_trace(),
            fail_arg_types.len(),
        );
    }
}

/// resume.py VStrPlainInfo.allocate / resume.py
/// VUniPlainInfo.allocate parity — materialize a Plain string/unicode
/// virtual from per-character fieldnums. Frontend implements via
/// `backend.bh_newstr` + `backend.bh_strsetitem` (or the unicode
/// variants). Returns the materialized string pointer as i64.
pub type MaterializeStrPlainFn = fn(is_unicode: bool, chars: &[i64]) -> i64;

/// resume.py concat_strings parity — materialize a Concat / Slice string
/// virtual by invoking `cpu.bh_call_r(func, args_i, args_r, descr)`.
/// Concat: args_i=[], args_r=[left, right] (resume.py concat_strings /
/// resume.py concat_unicodes). Slice: args_i=[start, stop], args_r=[str]
/// (resume.py slice_string / resume.py slice_unicode, stop = start + length).
pub type MaterializeStrCallFn = fn(
    is_unicode: bool,
    func: i64,
    calldescr: &majit_ir::DescrRef,
    args_i: &[i64],
    args_r: &[i64],
) -> i64;

thread_local! {
    static MATERIALIZE_STR_PLAIN_FN: std::cell::Cell<Option<MaterializeStrPlainFn>> =
        const { std::cell::Cell::new(None) };
    static MATERIALIZE_STR_CALL_FN: std::cell::Cell<Option<MaterializeStrCallFn>> =
        const { std::cell::Cell::new(None) };
}

/// Register the VStrPlain/VUniPlain materialization callback.
/// Called from pyre-jit init.
pub fn register_materialize_str_plain(f: MaterializeStrPlainFn) {
    MATERIALIZE_STR_PLAIN_FN.with(|c| c.set(Some(f)));
}

/// Register the VStrConcat/VStrSlice/VUniConcat/VUniSlice materialization
/// callback. Called from pyre-jit init.
pub fn register_materialize_str_call(f: MaterializeStrCallFn) {
    MATERIALIZE_STR_CALL_FN.with(|c| c.set(Some(f)));
}

/// JitFrame field descriptors supplied by the interpreter crate so the
/// GC rewriter's `handle_call_assembler` pass (rewrite.py) can
/// emit the correct GC_LOAD / GC_STORE sequence for callee jitframes.
#[derive(Clone)]
pub struct JitFrameLayoutInfo {
    pub jitframe_descrs: Option<majit_gc::rewrite::JitFrameDescrs>,
}

static JITFRAME_LAYOUT: OnceLock<JitFrameLayoutInfo> = OnceLock::new();

pub fn register_jitframe_layout(info: JitFrameLayoutInfo) {
    let _ = JITFRAME_LAYOUT.set(info);
}

/// Register a force callback for call_assembler guard failures.
pub fn register_call_assembler_force(f: extern "C" fn(i64) -> i64) {
    let _ = CALL_ASSEMBLER_FORCE_FN.set(f);
}

static CALL_ASSEMBLER_UNBOX_INT_FN: OnceLock<fn(i64) -> i64> = OnceLock::new();

pub fn register_call_assembler_unbox_int(f: fn(i64) -> i64) {
    let _ = CALL_ASSEMBLER_UNBOX_INT_FN.set(f);
}

/// rpython/jit/backend/llsupport/llmodel.py `insert_stack_check`
/// parity. Mirrors the dynasm-side address registration API so the
/// interpreter can install the three RPython-style probe addresses
/// uniformly across backends.
///
/// Cranelift does not emit an inline SP probe today; the prologue
/// calls [`register_prologue_probe_addr`]'s registered function (which
/// combines fast path + slowpath in one call) because Cranelift IR
/// does not expose a "read current SP" intrinsic. When such an
/// intrinsic lands, the prologue emitter will switch to the
/// `MOV [endaddr]; SUB sp; CMP [lengthaddr]; BLR slowpath` sequence
/// matching `assembler.py:1085-1091`, consuming the three RPython-
/// style addresses below directly.
#[derive(Copy, Clone, Debug)]
pub struct StackCheckAddresses {
    pub end_adr: usize,
    pub length_adr: usize,
    pub slowpath_addr: usize,
}

static STACK_CHECK_ADDRS: OnceLock<StackCheckAddresses> = OnceLock::new();

pub fn register_stack_check_addresses(end_adr: usize, length_adr: usize, slowpath_addr: usize) {
    let _ = STACK_CHECK_ADDRS.set(StackCheckAddresses {
        end_adr,
        length_adr,
        slowpath_addr,
    });
}

pub fn stack_check_addresses() -> Option<StackCheckAddresses> {
    STACK_CHECK_ADDRS.get().copied()
}

/// Address of the combined fast-path + slowpath stack check fallback.
/// Normal Cranelift prologues use [`stack_check_addresses`] to emit the
/// same inline fast path as dynasm and call the slowpath only on a miss.
/// This fallback remains for backend-only tests that register just the
/// combined probe.
static PROLOGUE_PROBE_ADDR: OnceLock<usize> = OnceLock::new();

pub fn register_prologue_probe_addr(addr: usize) {
    let _ = PROLOGUE_PROBE_ADDR.set(addr);
}

pub fn prologue_probe_addr() -> Option<usize> {
    PROLOGUE_PROBE_ADDR.get().copied()
}

pub fn register_call_assembler_bridge(
    f: fn(*mut majit_backend::jitframe::JitFrame, usize, i64, bool) -> Option<i64>,
) {
    let _ = CALL_ASSEMBLER_BRIDGE_FN.set(f);
}

const CALL_ASSEMBLER_DEADFRAME_SENTINEL: u32 = u32::MAX - 1;
const CALL_ASSEMBLER_RESULT_VOID: u64 = 0;
const CALL_ASSEMBLER_RESULT_INT: u64 = 1;
const CALL_ASSEMBLER_RESULT_FLOAT: u64 = 2;
const CALL_ASSEMBLER_RESULT_REF: u64 = 3;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum CallAssemblerCallerId {
    RootLoop(usize),
    BridgeTrace(u64),
}

fn with_call_assembler_expectations<R>(
    f: impl FnOnce(&mut IndexMap<usize, IndexMap<CallAssemblerCallerId, u64>>) -> R,
) -> R {
    CALL_ASSEMBLER_EXPECTATIONS
        .try_with(|r| f(&mut r.borrow_mut()))
        .expect("CALL_ASSEMBLER_EXPECTATIONS TLS not available")
}

/// Drop-path variant: `CompiledLoopToken::free_loop_and_bridges` can run
/// during thread shutdown, after Rust has destroyed the `RefCell`
/// thread_local (see `std::thread::LocalKey::try_with`). Since the drop
/// path is discarding state anyway, silently no-op when TLS is gone.
fn try_call_assembler_expectations_drop(
    f: impl FnOnce(&mut IndexMap<usize, IndexMap<CallAssemblerCallerId, u64>>),
) {
    let _ = CALL_ASSEMBLER_EXPECTATIONS.try_with(|r| f(&mut r.borrow_mut()));
}

fn call_assembler_result_kind_name(kind: u64) -> &'static str {
    match kind {
        CALL_ASSEMBLER_RESULT_VOID => "void",
        CALL_ASSEMBLER_RESULT_INT => "int",
        CALL_ASSEMBLER_RESULT_FLOAT => "float",
        CALL_ASSEMBLER_RESULT_REF => "ref",
        _ => "unknown",
    }
}

/// `None` when the target exposes no `done_with_this_frame` FINISH.
/// A loop-greenkey target reached via `do_recursive_call(assembler_call=True)`
/// at an inline-frame loop header (pyjitpl.py) exits via guard-deopt, and a
/// segmented loop (`_create_segmented_trace_and_blackhole`) ends on
/// `ExitFrameWithExceptionDescrRef` after `GUARD_ALWAYS_FAILS`. Neither is
/// the portal result kind `_call_assembler_check_descr` (x86/assembler.py)
/// compares against (`jd.portal_finishtoken` / `make_and_attach_done_descrs`).
/// Callers skip the (cranelift-only) expectation check in that case.
fn actual_call_assembler_target_result_kind(
    fail_descrs: &[DescrRef],
) -> Result<Option<u64>, BackendError> {
    let Some(finish_descr) = fail_descrs.iter().find(|descr| {
        let fd = as_fd(descr);
        fd.is_finish() && !fd.is_exit_frame_with_exception()
    }) else {
        return Ok(None);
    };
    actual_call_assembler_result_kind(as_fd(finish_descr)).map(Some)
}

fn validate_call_assembler_target_result_kind(
    target_token: usize,
    expected_result_kind: u64,
    actual_result_kind: u64,
    context: &str,
) -> Result<(), BackendError> {
    if expected_result_kind == actual_result_kind {
        return Ok(());
    }
    Err(BackendError::Unsupported(format!(
        "call-assembler target {target_token} has incompatible {context}: expected {}, got {}",
        call_assembler_result_kind_name(expected_result_kind),
        call_assembler_result_kind_name(actual_result_kind),
    )))
}

fn validate_registered_target_against_call_assembler_expectations(
    target_token: usize,
    target: &RegisteredLoopTarget,
) -> Result<(), BackendError> {
    let expected_result_kinds: Vec<u64> = with_call_assembler_expectations(|m| {
        m.get(&target_token)
            .map(|target_expectations| target_expectations.values().copied().collect())
            .unwrap_or_default()
    });
    if expected_result_kinds.is_empty() {
        return Ok(());
    }

    let Some(actual_result_kind) = actual_call_assembler_target_result_kind(&target.fail_descrs)?
    else {
        return Ok(());
    };
    for expected_result_kind in expected_result_kinds {
        validate_call_assembler_target_result_kind(
            target_token,
            expected_result_kind,
            actual_result_kind,
            "callee finish result kind",
        )?;
    }
    Ok(())
}

fn remove_call_assembler_expectations_locked(
    expectations: &mut IndexMap<usize, IndexMap<CallAssemblerCallerId, u64>>,
    caller_id: CallAssemblerCallerId,
) {
    expectations.retain(|_, callers| {
        callers.swap_remove(&caller_id);
        !callers.is_empty()
    });
}

fn unregister_call_assembler_expectations(caller_id: CallAssemblerCallerId) {
    // `try_*_drop`: the token's `free_loop_and_bridges` path may run
    // during thread TLS teardown. See the drop-path comment on
    // `try_call_assembler_expectations_drop`.
    try_call_assembler_expectations_drop(|m| {
        remove_call_assembler_expectations_locked(m, caller_id)
    });
}

fn unregister_bridge_call_assembler_expectations(bridge: &BridgeData) {
    unregister_call_assembler_expectations(CallAssemblerCallerId::BridgeTrace(bridge.trace_id));
    for descr in &bridge.fail_descrs {
        if let Some(child_bridge) = fail_descr_bridge_ref(as_fd(descr)) {
            unregister_bridge_call_assembler_expectations(&child_bridge);
        }
    }
}

fn unregister_call_assembler_bridge_tree(fail_descrs: &[DescrRef]) {
    for descr in fail_descrs {
        if let Some(bridge) = fail_descr_bridge_ref(as_fd(descr)) {
            unregister_bridge_call_assembler_expectations(&bridge);
        }
    }
}

fn collect_call_assembler_expectations(
    ops: &[OpRc],
) -> Result<IndexMap<usize, (u64, Arc<JitCellToken>)>, BackendError> {
    let mut expectations = IndexMap::new();
    for op in ops {
        let opcode = op.opcode;
        if !matches!(
            opcode,
            OpCode::CallAssemblerI
                | OpCode::CallAssemblerR
                | OpCode::CallAssemblerF
                | OpCode::CallAssemblerN
        ) {
            continue;
        }
        let descr = op.getdescr().ok_or_else(|| {
            unsupported_semantics(opcode, "call-assembler op must have a descriptor")
        })?;
        let call_descr = descr.as_call_descr().ok_or_else(|| {
            unsupported_semantics(opcode, "call-assembler descriptor must be a CallDescr")
        })?;
        let token = call_assembler_jitcell_token(&descr).ok_or_else(|| {
            unsupported_semantics(
                opcode,
                "call-assembler descriptor must provide a compiled target token",
            )
        })?;
        let target_token = token.identity_key();
        let expected_result_kind = expected_call_assembler_result_kind(call_descr)?;
        if let Some(&(previous, _)) = expectations.get(&target_token) {
            validate_call_assembler_target_result_kind(
                target_token,
                previous,
                expected_result_kind,
                "caller result expectation",
            )?;
        }
        expectations.insert(target_token, (expected_result_kind, Arc::clone(token)));
    }
    Ok(expectations)
}

fn install_call_assembler_expectations(
    caller_id: CallAssemblerCallerId,
    ops: &[OpRc],
) -> Result<(), BackendError> {
    let expectations = collect_call_assembler_expectations(ops)?;

    for (&target_token, &(expected_result_kind, ref token)) in &expectations {
        if let Some(target) = lookup_call_assembler_target(token) {
            // A null `code_ptr` has no compiled finish exits, so
            // `fail_descrs` is empty. Defer the actual-result-kind check to a
            // later real registration, where `register_call_assembler_target`
            // runs `validate_registered_target_against_call_assembler_expectations`
            // against the real finish descrs.
            if target.code_ptr.is_null() {
                continue;
            }
            if let Some(actual_result_kind) =
                actual_call_assembler_target_result_kind(&target.fail_descrs)?
            {
                validate_call_assembler_target_result_kind(
                    target_token,
                    expected_result_kind,
                    actual_result_kind,
                    "callee finish result kind",
                )?;
            }
        }
    }

    with_call_assembler_expectations(|registry| -> Result<(), BackendError> {
        for (&target_token, &(expected_result_kind, _)) in &expectations {
            if let Some(callers) = registry.get(&target_token) {
                for (&other_caller, &other_expected_kind) in callers {
                    if other_caller != caller_id {
                        validate_call_assembler_target_result_kind(
                            target_token,
                            expected_result_kind,
                            other_expected_kind,
                            "caller result expectation",
                        )?;
                    }
                }
            }
        }

        remove_call_assembler_expectations_locked(registry, caller_id);
        for (&target_token, &(expected_result_kind, _)) in &expectations {
            registry
                .entry_or_default(target_token)
                .insert(caller_id, expected_result_kind);
        }
        Ok(())
    })
}

fn register_call_assembler_target(
    token: &JitCellToken,
    compiled: &CompiledLoop,
) -> Result<(), BackendError> {
    let entry_code = compiled.entry_code_ptr.load(Ordering::Acquire) as *const u8;
    let entry_body = compiled.entry_body_ptr.load(Ordering::Acquire) as *const u8;
    let depth = compiled.frame_depth as i64;
    let base_ofs = JF_FRAME_ITEM0_OFS as i64;
    let clt = token.compiled_loop_token_expect();
    // Built before any publish: `RegisteredLoopTarget` reads compiled
    // fields and the token's existing identity, not `_ll_function_addr`,
    // `_ll_initial_locs` or `frame_info`.
    let target = RegisteredLoopTarget {
        trace_id: compiled.trace_id,
        green_key: token.green_key(),
        code_ptr: entry_code,
        body_ptr: entry_body,
        fail_descrs: compiled.fail_descrs.clone(),
        fail_descr_cells: compiled.fail_descr_cells.clone(),
        num_inputs: compiled.num_inputs,
        num_ref_roots: compiled.num_ref_roots,
        max_output_slots: compiled.max_output_slots,
        inputarg_types: token.inputarg_types().to_vec(),
        index_of_virtualizable: token
            .virtualizable_arg_index()
            .map(|i| i as i32)
            .unwrap_or(-1),
        compiled_loop_token: Arc::downgrade(&clt),
        cpu_attachments: Arc::clone(&compiled.cpu_attachments),
    };
    validate_registered_target_against_call_assembler_expectations(token.identity_key(), &target)?;
    // `x86/assembler.py assemble_loop` publishes
    // `looptoken._ll_function_addr = rawstart + functionpos` only after
    // the loop is fully assembled. The host-ABI wrapper stays on
    // `entry_code_ptr` for `execute_token`; CALL_ASSEMBLER and the
    // wrapper's key-0 arm enter `call_header_stub`. Redirect overlays
    // that stub and never rewrites this slot.
    token.set_ll_function_addr(compiled.call_header_stub_ptr);
    clt.set_ca_unregister(token.identity_key(), unregister_call_assembler_target);
    // `regalloc.py` `_set_initial_bindings`: contiguous layout
    // → `locs[i] = i * SIZEOFSIGNED`.
    *clt._ll_initial_locs.lock() = (0..compiled.num_inputs).map(|i| (i as i32) * 8).collect();
    // `jitframe.py` `jitframeinfo_update_depth`. The base_ofs is
    // shifted by `GcHeader::SIZE` because pyre's nursery allocator
    // returns the JITFRAME pointer past an 8-byte GcHeader; the depth
    // field counts payload slots after the header.
    clt.frame_info
        .lock()
        .update_frame_depth(base_ofs + GcHeader::SIZE as i64, depth);
    *clt.call_assembler_target.write() = Some(Arc::new(target));
    Ok(())
}

fn unregister_call_assembler_target(clt: &CompiledLoopToken, token_key: usize) {
    unregister_call_assembler_expectations(CallAssemblerCallerId::RootLoop(token_key));
    let removed = clt.call_assembler_target.write().take();
    if let Some(target) = removed.and_then(|any| any.downcast::<RegisteredLoopTarget>().ok()) {
        unregister_call_assembler_bridge_tree(&target.fail_descrs);
    }
}

/// `rewrite.py handle_call_assembler`: the CALL_ASSEMBLER descr's
/// `loop_token.compiled_loop_token`, and what the backend assembled for it.
fn lookup_call_assembler_target(token: &JitCellToken) -> Option<Arc<RegisteredLoopTarget>> {
    let clt = token.compiled_loop_token()?;
    let target = clt.call_assembler_target.read().clone()?;
    target.downcast::<RegisteredLoopTarget>().ok()
}

/// The target a CALL_ASSEMBLER shim was handed, as the address of the
/// descr's `JitCellToken`.
///
/// # Safety
/// `token_addr` is `Arc::as_ptr` of a `JitCellToken` that is still alive:
/// the calling loop's token keeps it through `record_jump_to`
/// (`compile.py record_loop_or_bridge`), or it is the calling loop itself.
unsafe fn call_assembler_target_at(token_addr: usize) -> Arc<RegisteredLoopTarget> {
    let token = unsafe { &*(token_addr as *const JitCellToken) };
    let clt = unsafe { &*token.compiled_loop_token_ptr() };
    clt.call_assembler_target
        .read()
        .clone()
        .and_then(|any| any.downcast::<RegisteredLoopTarget>().ok())
        .unwrap_or_else(|| panic!("missing call_assembler target token {token_addr:#x}"))
}

/// `x86/assembler.py redirect_call_assembler` checks first
/// (`assert old_nbargs == new_nbargs`) and only then copies frame info
/// and patches. Returns the looked-up new target so the caller can
/// mutate `old` and then [`publish_redirect_call_assembler_target`].
fn validate_redirect_call_assembler_target(
    old: &JitCellToken,
    new: &JitCellToken,
) -> Result<Option<Arc<RegisteredLoopTarget>>, BackendError> {
    let Some(new_target) = lookup_call_assembler_target(new) else {
        return Ok(None);
    };
    if let Some(old_target) = lookup_call_assembler_target(old)
        && old_target.inputarg_types != new_target.inputarg_types
    {
        return Err(BackendError::Unsupported(format!(
            "call-assembler redirect from token {} to {} changed input types",
            old.number(),
            new.number()
        )));
    }
    validate_registered_target_against_call_assembler_expectations(
        old.identity_key(),
        &new_target,
    )?;
    Ok(Some(new_target))
}

/// `x86/assembler.py redirect_call_assembler` patches the old loop's entry
/// to jump to the new one. Code that calls the old token enters what its
/// CLT names, so the old CLT now names the new loop.
fn publish_redirect_call_assembler_target(
    old: &JitCellToken,
    new_target: Arc<RegisteredLoopTarget>,
) {
    if let Some(clt) = old.compiled_loop_token() {
        *clt.call_assembler_target.write() = Some(new_target);
    }
}

fn store_call_assembler_deadframe(frame: DeadFrame) -> u64 {
    let handle = NEXT_CALL_ASSEMBLER_DEADFRAME_HANDLE.with(|cell| {
        let h = cell.get();
        cell.set(h + 1);
        h
    });
    assert!(handle != 0, "call_assembler deadframe handle overflowed");
    CALL_ASSEMBLER_DEADFRAMES.with(|map| {
        map.borrow_mut().insert(handle, frame);
    });
    handle
}

fn take_call_assembler_deadframe(handle: u64) -> Option<DeadFrame> {
    CALL_ASSEMBLER_DEADFRAMES.with(|map| map.borrow_mut().swap_remove(&handle))
}

/// Read typed values from a deadframe, dispatching on per-slot type.
/// RPython: cpu.get_{int,ref,float}_value(deadframe, i).
fn raw_values_from_deadframe_typed(
    frame: &DeadFrame,
    types: &[Type],
) -> Result<Vec<i64>, BackendError> {
    types
        .iter()
        .enumerate()
        .map(|(i, tp)| match tp {
            Type::Int => get_int_from_deadframe(frame, i),
            Type::Ref => get_ref_from_deadframe(frame, i).map(|value| value.0 as i64),
            Type::Float => get_float_from_deadframe(frame, i).map(|value| value.to_bits() as i64),
            Type::Void => Ok(0),
        })
        .collect()
}

fn finish_result_from_deadframe(frame: &DeadFrame) -> Result<i64, BackendError> {
    let (fail_arg_types, is_exit_frame_with_exception) = {
        let descr = get_latest_descr_from_deadframe(frame)?;
        assert!(descr.is_finish(), "expected finish deadframe");
        (
            descr.fail_arg_types().to_vec(),
            descr.is_exit_frame_with_exception(),
        )
    };
    if is_exit_frame_with_exception {
        let value = get_ref_from_deadframe(frame, 0)?.0 as i64;
        // compile.py ExitFrameWithExceptionDescrRef.handle_fail:
        // raise jitexc.ExitFrameWithExceptionRef(value).  Dynasm's
        // CALL_ASSEMBLER helper publishes the same pending exception;
        // Cranelift must do it here instead of routing this FINISH descr
        // through guard-only blackhole resume.
        jit_exc_raise(value);
        return Ok(value);
    }
    match fail_arg_types.as_slice() {
        [] => Ok(0),
        [Type::Int] => get_int_from_deadframe(frame, 0),
        // compile.py DoneWithThisFrameDescrRef.get_result reads the
        // slot through `cpu.get_ref_value(deadframe, 0)` and leaves it there —
        // the same read the exception arm above makes.
        [Type::Ref] => Ok(get_ref_from_deadframe(frame, 0)?.0 as i64),
        [Type::Float] => Ok(get_float_from_deadframe(frame, 0)?.to_bits() as i64),
        [Type::Void] => Ok(0),
        other => Err(BackendError::Unsupported(format!(
            "unsupported call_assembler finish result layout: {other:?}"
        ))),
    }
}

fn call_assembler_finish_or_blackhole_deadframe(frame: DeadFrame) -> Option<i64> {
    // `compile.py:710-716 resume_in_blackhole(descr, deadframe)` parity:
    // the descr is the sole identity carrier crossing the C-ABI; the
    // receiver derives green_key (memmgr-evicted JCT recovery via
    // `frame.pycode`), trace_id, and fail_index from the descr Arc.
    //
    // The blackhole hook recovers its descr via
    // `Backend::fail_descr_arc_from_addr` → `recover_fail_descr_cell`,
    // which requires `descr_addr` to be a `FailDescrCell` thin pointer.
    // The deadframe carries only `DescrRef`, so wrap it in a fresh cell
    // and bake that cell's address.  The recovery inside the BH call
    // bumps the strong refcount before returning, so the local cell can
    // safely drop after BH completes.
    let (is_finish, fail_descr_arc, frame_ptr) = {
        let jf = frame.as_jitframe()?;
        let fail_descr = jf.fail_descr.to_arc();
        let fd = as_fd(&fail_descr);
        let is_finish = fd.is_finish();
        let frame_ptr = jf.jf_gcref().0 as *mut majit_backend::jitframe::JitFrame;
        (is_finish, fail_descr, frame_ptr)
    };
    if is_finish {
        return finish_result_from_deadframe(&frame).ok();
    }

    let blackhole = CALL_ASSEMBLER_BLACKHOLE_FN.get()?;
    let cell = majit_ir::FailDescrCell::wrap(fail_descr_arc);
    let descr_addr = majit_ir::FailDescrCell::thin_ptr(&cell);
    let result = blackhole(descr_addr, frame_ptr);
    drop(cell);
    result
}

fn take_call_assembler_deadframe_from_outputs(outputs: &[i64]) -> DeadFrame {
    let handle = outputs
        .first()
        .copied()
        .unwrap_or_else(|| panic!("missing call_assembler deadframe handle slot"))
        as u64;
    take_call_assembler_deadframe_from_handle(handle)
}

fn take_call_assembler_deadframe_from_handle(handle: u64) -> DeadFrame {
    assert!(handle != 0, "missing call_assembler deadframe handle");
    take_call_assembler_deadframe(handle)
        .unwrap_or_else(|| panic!("unknown call_assembler deadframe handle {handle}"))
}

/// Takes the run's `JitExecResult` rather than an extracted output vector: the
/// handle lives in exit slot 0 and the slots are still in the frame the run
/// returned, so `llmodel.py grab_exc_value`'s read-through-the-frame answers this
/// without materialising the other slots first. The dispatch loops that call
/// this reach it on every exit, and all but the sentinel one discard the
/// vector unread.
fn maybe_take_call_assembler_deadframe(fail_index: u32, exec: &JitExecResult) -> Option<DeadFrame> {
    if fail_index != CALL_ASSEMBLER_DEADFRAME_SENTINEL {
        return None;
    }

    Some(take_call_assembler_deadframe_from_handle(
        exec.get_jf_int(0) as u64,
    ))
}

fn actual_call_assembler_result_kind(descr: &dyn FailDescr) -> Result<u64, BackendError> {
    match descr.fail_arg_types() {
        [] | [Type::Void] => Ok(CALL_ASSEMBLER_RESULT_VOID),
        [Type::Int] => Ok(CALL_ASSEMBLER_RESULT_INT),
        [Type::Float] => Ok(CALL_ASSEMBLER_RESULT_FLOAT),
        [Type::Ref] => Ok(CALL_ASSEMBLER_RESULT_REF),
        other => Err(BackendError::Unsupported(format!(
            "call-assembler target exposes unsupported finish result layout: {other:?}"
        ))),
    }
}

/// llmodel.py force() as a free function.
/// force_token is the JitFrame pointer (FORCE_TOKEN returns jf_ptr).
pub fn force_token_to_dead_frame(force_token: GcRef) -> DeadFrame {
    assert!(force_token.0 != 0, "force_token_to_dead_frame: null token");
    let jf_ptr = force_token.0 as *mut i64;
    let jf_ptr = jitframe_resolve(jf_ptr);
    // frame.jf_descr = frame.jf_force_descr
    let jf_force_descr = unsafe { *jf_ptr.add(JF_FORCE_DESCR_OFS as usize / 8) };
    unsafe { *jf_ptr.add(JF_DESCR_OFS as usize / 8) = jf_force_descr };
    let jf_gcref = GcRef(jf_ptr as usize);
    assert!(
        jf_force_descr != 0,
        "force_token_to_dead_frame: jf_force_descr is null"
    );
    // `history.py` `AbstractDescr.show(cpu, descr_gcref)`
    // parity.  `jf_force_descr` carries the per-emission
    // `FailDescrCell` thin pointer baked at codegen
    // (`collect_guards`).  Recovery is a pure
    // `Arc::from_raw` against the cell, with the strong refcount
    // held by the owning `CompiledLoop::fail_descr_cells` for the
    // life of the executing JIT code.
    let fail_descr = unsafe { majit_ir::recover_fail_descr_cell(jf_force_descr as usize) };
    // `llmodel.py force` returns the resolved frame itself.  The frame
    // is the one the compiled run is executing in — still on the JF shadow
    // stack, inside the residual call that armed `jf_force_descr` — so this
    // deadframe borrows it: the call site pushed `jf_gcmap` before the call and
    // clears it with `pop_gcmap` on return, and releasing it here would leave
    // the frame's spilled `Ref` slots untraced for the rest of the call.
    DeadFrame::JitFrame(JitFrameDeadFrame::borrowing(
        jf_gcref,
        ExitDescr::owned(fail_descr),
        None,
    ))
}

fn deadframe_from_jitframe(
    jf_gcref: GcRef,
    fail_descr: ExitDescr,
    heap_owner: Option<FrameHeapOwner>,
) -> DeadFrame {
    DeadFrame::JitFrame(JitFrameDeadFrame::new(
        jf_gcref, fail_descr, None, heap_owner,
    ))
}

/// `compile.py DoneWithThisFrameDescrRef`, and not
/// `ExitFrameWithExceptionDescrRef` (also `fail_index() == u32::MAX` and
/// `[Type::Ref]`, but `is_exit_frame_with_exception`).
fn is_done_with_this_frame_ref(descr: &dyn FailDescr) -> bool {
    descr.is_finish()
        && !descr.is_exit_frame_with_exception()
        && descr.fail_arg_types() == [Type::Ref]
}

/// `DoneWithThisFrameDescrRef.get_result` → `llmodel.py get_ref_value`.
///
/// `JitFrameDeadFrame::slot_of`: an empty `rd_locs` is the fail-arg index
/// (slot 0 here). A `0xFFFF` hole has no word. The length check is
/// `JitFrameDeadFrame::get_int_at_slot`.
fn ref_finish_word(
    frame: *const majit_backend::jitframe::JitFrame,
    descr: &dyn FailDescr,
) -> usize {
    let locs = descr.rd_locs();
    let slot = if let Some(&pos) = locs.get(0) {
        if pos == 0xFFFF {
            return 0;
        }
        pos as usize
    } else {
        0
    };
    let frame_len = unsafe { majit_backend::jitframe::JitFrame::frame_length(frame) };
    if slot >= frame_len as usize {
        return 0;
    }
    unsafe { majit_backend::llmodel::get_ref_value_direct(frame, slot) }
}

/// `warmstate.py execute_assembler` for a ref portal.
///
/// The result word is loaded, then the frame is released: a nursery frame's
/// `heap_owner` is `None` (the collector's object; `JitFrameDeadFrame::new`
/// is what would have rooted it), a host frame drops `FrameHeapOwner`. The
/// compiled return, `jitframe_resolve`, the descr match, and this load do
/// not allocate and do not hit a safepoint, and that release does not enter
/// the collector, so the address is not rooted. Every other descr builds
/// the deadframe `deadframe_from_jitframe` has always built.
fn release_ref_finish_or_deadframe(
    release_ref_finish: bool,
    exec: JitExecResult,
    fail_descr: ExitDescr,
) -> Result<usize, DeadFrame> {
    if release_ref_finish {
        let word = {
            let fd = fail_descr.as_fail_descr();
            if is_done_with_this_frame_ref(fd) {
                let frame = exec.jf_gcref.0 as *const majit_backend::jitframe::JitFrame;
                Some(ref_finish_word(frame, fd))
            } else {
                None
            }
        };
        if let Some(word) = word {
            drop(exec);
            return Ok(word);
        }
    }
    Err(deadframe_from_jitframe(
        exec.jf_gcref,
        fail_descr,
        exec.heap_owner,
    ))
}

fn expect_deadframe(result: Result<usize, DeadFrame>) -> DeadFrame {
    match result {
        Err(frame) => frame,
        // `release_ref_finish` is false on every caller of this.
        Ok(_) => unreachable!("ref-finish release is off on this entry"),
    }
}

/// Post-call handling for one compiled entry. Shared by
/// `execute_with_inputs_at_dispatch_key` and the raw done-ref miss path.
///
/// `llmodel.py execute_token` returns the frame; `warmstate.py
/// execute_assembler` then tests `isinstance(fail_descr,
/// DoneWithThisFrameDescrRef)`. An external JUMP (`assembler.py
/// closing_jump` fall-through) re-enters the target; `assembler.py
/// call_assembler` consumes the sentinel and keeps the caller prefix.
enum CompiledExit {
    Done(Result<usize, DeadFrame>),
    Jump {
        dispatch_key: u32,
        code_ptr: *const u8,
        fail_descrs: Box<[DescrRef]>,
        num_ref_roots: usize,
        max_output_slots: usize,
        inputs: Vec<i64>,
    },
}

fn handle_compiled_exit(
    compiled: &CompiledLoop,
    mut exec: JitExecResult,
    cur_fail_descrs: &[DescrRef],
    cur_max_output_slots: usize,
    release_ref_finish: bool,
) -> CompiledExit {
    let fail_index = exec.fail_index;
    let direct_descr = exec.direct_descr.take();

    if let Some(frame) = maybe_take_call_assembler_deadframe(fail_index, &exec) {
        return CompiledExit::Done(Err(frame));
    }

    let fail_descr = if let Some(descr) = direct_descr {
        descr
    } else if (fail_index as usize) < cur_fail_descrs.len() {
        ExitDescr::owned(cur_fail_descrs[fail_index as usize].clone())
    } else {
        let found = compiled.fail_descrs.iter().find_map(|d| {
            let guard = fail_descr_bridge_ref(as_fd(d));
            guard.as_ref().and_then(|b| {
                find_fail_descr_in_fail_descrs(&b.fail_descrs, b.trace_id, fail_index)
            })
        });
        ExitDescr::owned(found.unwrap_or_else(|| {
            cur_fail_descrs
                .last()
                .cloned()
                .unwrap_or_else(|| compiled.fail_descrs[0].clone())
        }))
    };
    // `compile.py` `_DoneWithThisFrameDescr.final_descr = True` is a
    // class attribute, i.e. a field load after translation. The FINISH
    // family answers `fail_index()` with `u32::MAX`
    // (`majit-backend/src/finish_descrs.rs`) and the resolution above
    // already keyed on that, so the three trait queries below would
    // ask the descr what this word has already said. The arm is a
    // SUPERSET of `is_finish()` — a `PropagateExceptionDescr` answers
    // `u32::MAX` too and is not final — and it is right only because
    // the fall-through return is byte-identical. Anything added
    // between the two returns below has to be re-checked here.
    debug_assert!(
        fail_index != u32::MAX || {
            let fd = fail_descr.as_fail_descr();
            !fd.is_external_jump() && !fd.is_resume_guard() && !fd.is_resume_guard_copied()
        },
        "a u32::MAX fail_index must be a final or propagate descr, never a guard"
    );
    if fail_index == u32::MAX {
        return CompiledExit::Done(release_ref_finish_or_deadframe(
            release_ref_finish,
            exec,
            fail_descr,
        ));
    }
    let fail_descr_fd = fail_descr.as_fail_descr();

    if fail_descr_fd.is_external_jump() {
        slice_x2_probe::record_execute_with_inputs_hit();
        let target_descr = fail_descr_fd.target_descr();
        let target_entry = target_descr
            .as_ref()
            .and_then(lookup_loop_target)
            .expect("external JUMP target must be a registered LoopTargetDescr");
        let dispatch_key = target_descr
            .as_ref()
            .map(host_reentry_dispatch_key)
            .unwrap_or(0);
        let inputs = exec.extract_outputs(cur_max_output_slots.max(1));
        return CompiledExit::Jump {
            dispatch_key,
            code_ptr: target_entry.code_ptr,
            fail_descrs: target_entry.fail_descrs.clone(),
            num_ref_roots: target_entry.num_ref_roots,
            max_output_slots: target_entry.max_output_slots,
            inputs,
        };
    }
    if fail_descr_fd.is_finish() {
        return CompiledExit::Done(release_ref_finish_or_deadframe(
            release_ref_finish,
            exec,
            fail_descr,
        ));
    }

    // llgraph/runner.py fail_guard → ExecutionFinished (LLDeadFrame).
    // Attached bridges dispatch in-code (`patch_jump_for_descr`);
    // reaching here means the descr has no bridge.
    CompiledExit::Done(Err(deadframe_from_jitframe(
        exec.jf_gcref,
        fail_descr,
        exec.heap_owner,
    )))
}

pub fn set_savedata_ref_on_deadframe(
    frame: &mut DeadFrame,
    data: GcRef,
) -> Result<(), BackendError> {
    let jf = frame
        .as_jitframe_mut()
        .ok_or_else(|| BackendError::Unsupported("expected JitFrameDeadFrame".to_string()))?;
    // llmodel.py set_savedata_ref is a GCREF store. Root `data` across
    // the barrier so a moving collection forwards AllVirtuals before
    // the field write.
    let mut data_slot = data.0 as i64;
    let depth = majit_gc::shadow_stack::resume_ref_roots_depth();
    unsafe {
        majit_gc::shadow_stack::push_resume_ref_roots(std::slice::from_mut(&mut data_slot));
    }
    majit_gc::gc_write_barrier(jf.jf_gcref());
    majit_gc::shadow_stack::pop_resume_ref_roots_to(depth);
    jf.set_savedata_ref(GcRef(data_slot as usize));
    Ok(())
}

pub fn get_latest_descr_from_deadframe(frame: &DeadFrame) -> Result<&dyn FailDescr, BackendError> {
    // llmodel.py get_latest_descr: cast deadframe → JITFRAMEPTR,
    // read jf_descr, show() → AbstractFailDescr.
    let jf = frame
        .as_jitframe()
        .ok_or_else(|| BackendError::Unsupported("expected JitFrameDeadFrame".to_string()))?;
    Ok(jf.fail_descr.as_fail_descr())
}

/// Owned-Arc counterpart of [`get_latest_descr_from_deadframe`].
///
/// `cpu.get_latest_descr(deadframe)` (`history.py:125`) returns the
/// metainterp `AbstractFailDescr` Arc the optimizer stamped onto
/// `op.descr` (or the cpu-attached singleton for FINISH exits).
/// `JitFrameDeadFrame.fail_descr` IS that Arc — no wrapper indirection
/// (no wrapper indirection).
pub fn get_latest_descr_arc_from_deadframe(
    frame: &DeadFrame,
) -> Result<Arc<dyn majit_ir::Descr>, BackendError> {
    let jf = frame
        .as_jitframe()
        .ok_or_else(|| BackendError::Unsupported("expected JitFrameDeadFrame".to_string()))?;
    Ok(jf.fail_descr.to_arc())
}

