    #[expect(
        dead_code,
        reason = "ref-forcing residual-call test fixture retained for parity"
    )]
    extern "C" fn maybe_force_and_return_ref(
        force_token: i64,
        flag: i64,
        _runtime_id: i64,
        return_ref: i64,
    ) -> i64 {
        if flag != 0 {
            let mut deadframe = force_token_to_dead_frame(GcRef(force_token as usize));
            let preview_live = get_ref_from_deadframe(&deadframe, 2).unwrap();
            set_savedata_ref_on_deadframe(&mut deadframe, preview_live).unwrap();
            with_cranelift_gc_required(|gc| gc.collect_nursery());
            let preview_result = get_ref_from_deadframe(&deadframe, 1).unwrap();
            let preview_live = get_ref_from_deadframe(&deadframe, 2).unwrap();
            let preview_return = get_ref_from_deadframe(&deadframe, 3).unwrap();
            let mut values = may_force_ref_values().lock();
            values.push(preview_result.0);
            values.push(preview_live.0);
            values.push(preview_return.0);
            return get_ref_from_deadframe(&deadframe, 3).unwrap().0 as i64;
        }
        return_ref
    }

    /// Register JITFRAME on `gc` and tell the descr its id, which is what a
    /// frontend does before it installs its collector (`eval.rs build_gc`
    /// registers the shape, then `set_jitframe_type_id`, and only then
    /// `install_gc_standalone`). `check_jitframe_descr` requires that
    /// ordering of any collector that has a type registry.
    ///
    /// JITFRAME goes in AFTER whatever types the fixture registered for
    /// itself, so it is never id 0: eval.rs registers OBJECT / W_INT / W_FLOAT
    /// first, and a fixture that made JITFRAME the first type would be
    /// exercising an id the shipped configuration cannot produce.
    fn publish_jitframe_type(gc: &mut MiniMarkGC) -> u32 {
        let id = gc.register_type(majit_backend::jitframe::jitframe_type_info());
        gc.set_jitframe_type_id(id);
        id
    }

    /// [`publish_jitframe_type`] and the install, for the fixtures that build a
    /// collector and hand it straight to a fresh backend.
    fn backend_with_gc(mut gc: MiniMarkGC) -> CraneliftBackend {
        publish_jitframe_type(&mut gc);
        CraneliftBackend::with_gc_allocator(Box::new(gc))
    }

    /// A collector with a type registry may not be installed without its
    /// JITFRAME id, and the refusal is a panic rather than a fall-through to
    /// the off-GC `Vec` frame.
    ///
    /// The fall-through is what makes this worth a test: a `Vec` frame is not
    /// wrong-looking at the allocation, it is wrong four collections later,
    /// when the collector that was installed all along never traced the ref
    /// slots of a frame it does not own.
    ///
    /// `expected` names only "JITFRAME" because two refusals reach it. With
    /// nothing published the message is the missing-id one; if a sibling
    /// fixture on another thread republishes the atomic between the clear and
    /// the install, this collector — which has registered no type at all —
    /// fails the id-names-a-JITFRAME check instead. Both are the contract.
    #[test]
    #[should_panic(expected = "JITFRAME")]
    fn test_gc_install_without_published_jitframe_id_panics() {
        let _backend = CraneliftBackend::with_gc_allocator(Box::new(MiniMarkGC::new()));
    }

    /// The published id is resolved against the collector being installed, so
    /// an id minted in a DIFFERENT registry is refused at the install.
    ///
    /// Without the check it would be taken at face value and name whatever
    /// type sits at that index — the collector would then copy jitframes under
    /// some other shape's layout, which is the failure the hard-coded `2` in
    /// eval.rs's comment describes.
    #[test]
    #[should_panic(expected = "does not name a JITFRAME")]
    fn test_gc_install_with_a_foreign_jitframe_id_panics() {
        let mut gc = MiniMarkGC::new();
        let plain = gc.register_type(TypeInfo::simple(16));
        gc.set_jitframe_type_id(plain);
        let _backend = CraneliftBackend::with_gc_allocator(Box::new(gc));
    }

    /// An allocator with no type table keeps the off-GC `Vec` frame, and that
    /// is the whole of the exemption: it is not "no id published", it is "no
    /// registry to publish an id into". `TrackingGc` takes `GcAllocator`'s
    /// default `has_type_registry`, as every test double does.
    #[test]
    fn test_stub_gc_install_keeps_the_off_gc_frame() {
        let stub = TrackingGc::new(Arc::new(Mutex::new(TrackingGcState::default())));
        assert!(!majit_gc::GcAllocator::has_type_registry(&stub));
        let _backend = CraneliftBackend::with_gc_allocator(Box::new(stub));
        assert_eq!(cranelift_jitframe_type_id(), None);
    }

    fn make_gc_backend() -> CraneliftBackend {
        let mut gc = MiniMarkGC::with_config(GcConfig {
            nursery_size: 1 << 20,
            large_object_threshold: 1 << 20,
            ..GcConfig::default()
        });
        gc.register_type(TypeInfo::simple(16));
        backend_with_gc(gc)
    }

    /// The active GC is execution-thread state shared by every backend on the
    /// thread.  Dropping either the backend that installed it or an unrelated
    /// sibling must not make surviving compiled loops fall through to
    /// `HostHeapGc`; explicit runtime teardown owns that transition.
    #[test]
    fn dropping_a_backend_keeps_the_thread_gc_installed() {
        clear_gc_allocator();
        let owner = make_gc_backend();
        let jitframe_tid = cranelift_jitframe_type_id()
            .expect("the fixture installed a managed JITFRAME allocator");

        drop(CraneliftBackend::new());
        assert_eq!(cranelift_jitframe_type_id(), Some(jitframe_tid));

        drop(owner);
        assert_eq!(cranelift_jitframe_type_id(), Some(jitframe_tid));
        assert!(gc_box::present());
        clear_gc_allocator();
        assert!(
            !gc_box::present(),
            "clear_gc_allocator is the production path that releases the boxed collector"
        );
    }

    /// The call-assembler deadframe map is the same thread-owned slot as the
    /// active GC.  Dropping a sibling backend must not wipe a live handle or
    /// reset the counter out from under a surviving backend.
    #[test]
    fn dropping_a_backend_keeps_call_assembler_deadframes() {
        let first = store_call_assembler_deadframe(DeadFrame::boxed(1u64));
        drop(CraneliftBackend::new());
        let second = store_call_assembler_deadframe(DeadFrame::boxed(2u64));
        assert_ne!(
            first, second,
            "a sibling Drop must not reset the deadframe handle counter"
        );
        let first_frame = take_call_assembler_deadframe(first)
            .expect("a sibling Drop must not clear a live call_assembler deadframe");
        let second_frame = take_call_assembler_deadframe(second)
            .expect("a handle stored after a sibling Drop must still be takeable");
        match first_frame {
            DeadFrame::Boxed(value) => assert_eq!(value.downcast_ref::<u64>(), Some(&1)),
            _ => panic!("expected boxed first handle"),
        }
        match second_frame {
            DeadFrame::Boxed(value) => assert_eq!(value.downcast_ref::<u64>(), Some(&2)),
            _ => panic!("expected boxed second handle"),
        }
    }

    /// Publish the JitFrame layout descrs so the GC rewriter's
    /// handle_call_assembler pass (rewrite.py) can emit GC_LOAD /
    /// GC_STORE against callee jitframes. Mirrors the dynasm test layout
    /// (runner.rs install_call_assembler_test_layout); the offsets match
    /// the production cranelift mapping in pyre-jit call_jit.rs
    /// jitframe_layout_descrs. Reads the type id the install resolved, so it
    /// must run after `set_gc_allocator`.
    fn install_call_assembler_test_layout() {
        register_jitframe_layout(JitFrameLayoutInfo {
            jitframe_descrs: Some(majit_gc::rewrite::JitFrameDescrs {
                jitframe_tid: cranelift_jitframe_type_id()
                    .expect("call-assembler fixtures run on a GC-backed frame"),
                jitframe_fixed_size: majit_backend::jitframe::JITFRAME_FIXED_SIZE,
                jf_frame_info_ofs: majit_backend::jitframe::JF_FRAME_INFO_OFS,
                jf_descr_ofs: JF_DESCR_OFS,
                jf_force_descr_ofs: JF_FORCE_DESCR_OFS,
                jf_savedata_ofs: JF_SAVEDATA_OFS,
                jf_guard_exc_ofs: JF_GUARD_EXC_OFS,
                jf_forward_ofs: JF_FORWARD_OFS,
                jf_frame_ofs: JF_FRAME_OFS,
                jf_frame_baseitemofs: majit_backend::jitframe::FIRST_ITEM_OFFSET,
                jf_frame_lengthofs: JF_FRAME_OFS + majit_backend::jitframe::LENGTHOFS,
                sign_size: majit_backend::jitframe::SIGN_SIZE,
                jf_frame_itemsize: majit_backend::jitframe::SIGN_SIZE,
            }),
        });
    }

    /// GC-backed backend for CALL_ASSEMBLER tests:
    /// validate_call_assembler_rewrite_prereqs (compiler.rs) requires both a
    /// configured GC runtime and a registered JITFRAME layout. Build the GC
    /// like make_gc_backend, then install the layout once the install has
    /// resolved the JITFRAME type id.
    fn make_call_assembler_backend() -> CraneliftBackend {
        let mut gc = MiniMarkGC::with_config(GcConfig {
            nursery_size: 1 << 20,
            large_object_threshold: 1 << 20,
            ..GcConfig::default()
        });
        gc.register_type(TypeInfo::simple(16));
        let backend = backend_with_gc(gc);
        install_call_assembler_test_layout();
        backend
    }

    /// `llmodel.py` `llop.gc_writebarrier(lltype.Void, new_frame)`, and the
    /// barrier the framework transform emits for the ordinary GC-struct field
    /// store `frame.jf_forward = new_frame` (`llmodel.py`).
    ///
    /// `cranelift_realloc_frame` moves the old frame's ref slots into the new
    /// frame through raw pointer writes, and a frame reaches the old generation
    /// as soon as one minor collection promotes the one it finds on the shadow
    /// stack.  `large_object_threshold` here sits below the frame size, so both
    /// frames are born old and start with `TRACK_YOUNG_PTRS` set —
    /// `remember_young_pointer` clearing that flag is the observable, since an
    /// old-generation object can only lose it by being recorded in the
    /// remembered set.
    #[test]
    fn realloc_frame_write_barriers_both_frames() {
        let depth = 8usize;
        let header_words = JF_FRAME_ITEM0_OFS as usize / 8;
        let payload_bytes = (header_words + depth) * 8;

        let mut gc = MiniMarkGC::with_config(GcConfig {
            nursery_size: 1 << 20,
            large_object_threshold: 64,
            ..GcConfig::default()
        });
        gc.register_type(TypeInfo::simple(16));
        let _backend = backend_with_gc(gc);

        let type_id = cranelift_jitframe_type_id().expect("JITFRAME type id must be registered");
        let old = with_cranelift_gc_required(|gc| {
            gc.alloc_nursery_no_collect_typed(type_id, payload_bytes)
        });
        assert_ne!(old.0, 0, "old frame allocation failed");
        unsafe {
            std::ptr::write_bytes(old.0 as *mut u8, 0, payload_bytes);
            *((old.0 + JF_FRAME_LENGTH_OFS as usize) as *mut usize) = depth;
        }

        let tracks_young =
            |addr: usize| unsafe { (*header_of(addr)).has_flag(GcFlags::GCFLAG_TRACK_YOUNG_PTRS) };
        let in_nursery = |addr: usize| with_cranelift_gc_required(|gc| gc.is_nursery_object(addr));

        assert!(
            !in_nursery(old.0),
            "the old frame must be born old-gen here"
        );
        assert!(
            tracks_young(old.0),
            "an old-generation object starts out tracking young pointers"
        );

        let new_jf = unsafe { cranelift_realloc_frame(old.0 as *mut i64, depth * 2) };
        assert!(!new_jf.is_null(), "realloc returned no frame");

        assert!(
            !in_nursery(new_jf as usize),
            "the new frame must be born old-gen here, or the barrier under test \
             has nothing to record"
        );
        assert!(
            !tracks_young(new_jf as usize),
            "the copied frame items are old→young edges the barrier must remember"
        );
        assert!(
            !tracks_young(old.0),
            "`jf_forward` points at the new frame and must be remembered too"
        );
    }

    #[derive(Default)]
    struct TrackingGcState {
        collecting_allocs: usize,
        no_collect_allocs: usize,
        write_barriers: usize,
        added_roots: usize,
        removed_roots: usize,
    }

    struct TrackingGc {
        state: Arc<Mutex<TrackingGcState>>,
        allocations: Vec<Box<[u8]>>,
        nursery_free: usize,
        nursery_top: usize,
    }

    impl TrackingGc {
        fn new(state: Arc<Mutex<TrackingGcState>>) -> Self {
            Self {
                state,
                allocations: Vec::new(),
                nursery_free: 0,
                nursery_top: 0,
            }
        }

        fn alloc_payload(&mut self, payload_size: usize, collecting: bool) -> GcRef {
            let total_size = GcHeader::SIZE + payload_size.max(std::mem::size_of::<usize>());
            let mut buf = vec![0u8; total_size].into_boxed_slice();
            let ptr = buf.as_mut_ptr();
            unsafe {
                *(ptr as *mut GcHeader) = GcHeader::new(0);
            }
            let obj = GcRef(ptr as usize + GcHeader::SIZE);
            self.allocations.push(buf);
            let mut state = self.state.lock();
            if collecting {
                state.collecting_allocs += 1;
            } else {
                state.no_collect_allocs += 1;
            }
            obj
        }
    }

    impl GcAllocator for TrackingGc {
        fn alloc_nursery(&mut self, size: usize) -> GcRef {
            self.alloc_payload(size, true)
        }

        fn alloc_nursery_no_collect(&mut self, size: usize) -> GcRef {
            self.alloc_payload(size, false)
        }

        fn alloc_varsize(&mut self, base_size: usize, item_size: usize, length: usize) -> GcRef {
            self.alloc_payload(base_size + item_size * length, true)
        }

        fn alloc_varsize_no_collect(
            &mut self,
            base_size: usize,
            item_size: usize,
            length: usize,
        ) -> GcRef {
            self.alloc_payload(base_size + item_size * length, false)
        }

        fn write_barrier(&mut self, _obj: GcRef) {
            self.state.lock().write_barriers += 1;
        }

        fn jit_remember_young_pointer_from_array(&mut self, _obj: GcRef) {
            self.state.lock().write_barriers += 1;
        }

        fn remember_young_pointer_from_array2(
            &mut self,
            _obj: GcRef,
            _index: usize,
            _card_page_shift: u32,
        ) {
            self.state.lock().write_barriers += 1;
        }

        fn collect_nursery(&mut self) {}

        fn collect_full(&mut self) {}

        unsafe fn add_root(&mut self, _root: *mut GcRef) {
            self.state.lock().added_roots += 1;
        }

        fn remove_root(&mut self, _root: *mut GcRef) {
            self.state.lock().removed_roots += 1;
        }

        fn nursery_free(&self) -> *mut u8 {
            self.nursery_free as *mut u8
        }

        fn nursery_free_addr(&self) -> usize {
            std::ptr::addr_of!(self.nursery_free) as usize
        }

        fn nursery_top(&self) -> *const u8 {
            self.nursery_top as *const u8
        }

        fn nursery_top_addr(&self) -> usize {
            std::ptr::addr_of!(self.nursery_top) as usize
        }

        fn max_nursery_object_size(&self) -> usize {
            usize::MAX
        }
    }

    fn assert_compile_unsupported(
        inputargs: Vec<InputArgRc>,
        ops: Vec<majit_ir::OpRc>,
        token_number: u64,
        opcode: OpCode,
        expected_detail: &str,
    ) {
        let mut backend = CraneliftBackend::new();
        let token = JitCellToken::new(token_number as i64);
        let err = backend.compile_loop(&inputargs, &ops, &token).unwrap_err();
        match err {
            BackendError::Unsupported(msg) => {
                assert!(msg.contains(&format!("{opcode:?}")));
                assert!(
                    msg.contains(expected_detail),
                    "expected detail {expected_detail:?} in unsupported message {msg:?}"
                );
            }
            other => panic!("expected unsupported error, got {other:?}"),
        }
    }

