    #[test]
    fn test_count_to_million() {
        let mut backend = CraneliftBackend::new();

        let inputargs = vec![InputArg::new_int_rc(0)];
        // resoperation.py `InputArgInt.type = 'i'` parity: Label /
        // IntAdd / Jump args that reference the inputarg slot are
        // `InputArgInt` boxes, not `IntOp` results. The op-position
        // raw-keyed `constants` IndexMap (positions 100/101 below) is a
        // TODO mirroring `make_constant`'s op-position
        // inline-constant path; that part of the fixture is left alone.
        let ia0 = OpRef::input_arg_int(0);
        let ops = [
            mk_op(OpCode::Label, &[ia0], OpRef::NONE.raw()),
            mk_op(OpCode::IntAdd, &[ia0, OpRef::int_op(100)], 1),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::int_op(101)], 2),
            mk_op(OpCode::GuardTrue, &[OpRef::int_op(2)], OpRef::NONE.raw()),
            mk_op(OpCode::Jump, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        ops[3].setfailargs(smallvec::smallvec![rb(ia0)]);

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(100, 1i64);
        constants.insert(101, 1_000_000i64);
        backend.set_constants(constants);

        let token = JitCellToken::new(0);
        let info = backend.compile_loop(&inputargs, &ops, &token).unwrap();
        assert!(info.code_addr != 0);

        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        assert_eq!(backend.get_int_value(&frame, 0), 999_999);
        let clif = backend.last_body_clif.clone();
        assert!(
            guard_true_brif_fail_first_without_materialized_bool(&clif),
            "GuardTrue must brif the complemented icmp to the fail stub first, without materialising the bool:\n{clif}"
        );
    }

    /// IntLt + GuardTrue does not materialise the boolean (`uextend` of
    /// `icmp slt`). `implement_guard` `brif`s the complemented `icmp sge`
    /// to the fail stub (taken / first successor, a cold block).
    fn guard_true_brif_fail_first_without_materialized_bool(clif: &str) -> bool {
        fn block_name(header: &str) -> Option<&str> {
            header
                .split(|c: char| !c.is_ascii_alphanumeric())
                .find(|tok| {
                    tok.starts_with("block")
                        && tok.bytes().nth(5).is_some_and(|b| b.is_ascii_digit())
                })
        }
        let cold_blocks: indexmap::IndexSet<&str> = clif
            .lines()
            .map(str::trim)
            .filter(|t| t.starts_with("block") && t.ends_with(':') && t.contains("cold"))
            .filter_map(block_name)
            .collect();
        let mut slt: Option<&str> = None;
        let mut slt_uextend = false;
        let mut sge_names = indexmap::IndexSet::new();
        let mut fail_first = false;
        for line in clif.lines() {
            let t = line.trim();
            if slt.is_none() {
                if let Some((lhs, rhs)) = t.split_once(" = icmp")
                    && lhs.starts_with('v')
                    && rhs.contains("slt")
                {
                    slt = Some(lhs);
                }
            } else if let Some((_lhs, rhs)) = t.split_once(" = uextend.i64 ")
                && rhs.trim() == slt.unwrap()
            {
                slt_uextend = true;
            }
            if let Some((lhs, rhs)) = t.split_once(" = icmp")
                && lhs.starts_with('v')
                && rhs.contains("sge")
            {
                sge_names.insert(lhs);
            }
            if t.starts_with("brif ") {
                let uses_sge = t
                    .split(|c: char| !c.is_ascii_alphanumeric())
                    .any(|tok| sge_names.iter().any(|n| *n == tok));
                if uses_sge {
                    let fail_block = t.split_whitespace().nth(2).and_then(block_name);
                    if fail_block.is_some_and(|b| cold_blocks.contains(b)) {
                        fail_first = true;
                    }
                }
            }
        }
        fail_first && !slt_uextend
    }

    /// `compile.py` `PropagateExceptionDescr.handle_fail` through the exit
    /// reader: the compiled null check leaves `jf_descr` as the propagate
    /// descr (`_build_propagate_exception_path`), and the reader raises the
    /// grabbed value, or `memory_error` when `jf_guard_exc` is null.
    #[test]
    fn propagate_exception_exit_raises_through_the_reader() {
        // Leave the process-global provider alone. A stand-in address
        // is what a later test dereferences as an exception object.
        let memory_error = majit_backend::memory_error_singleton_ref();

        let mut backend = CraneliftBackend::new();
        let propagate: majit_ir::DescrRef = Arc::new(majit_backend::PropagateExceptionDescr::new());
        backend.set_propagate_exception_descr(Arc::clone(&propagate));
        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = [
            mk_op(
                OpCode::CheckMemoryError,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
            ),
            mk_op(
                OpCode::Finish,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
            ),
        ];
        let token = JitCellToken::new(70);
        backend
            .compile_loop(&inputargs, &ops, &token)
            .expect("compile CheckMemoryError");

        let exc_obj = 0i64;
        let exc = &exc_obj as *const i64 as i64;
        jit_exc_raise(exc);
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        let descr = backend.get_latest_descr_arc(&frame);
        assert!(Arc::ptr_eq(&descr, &propagate));
        let fd = descr.as_fail_descr().expect("propagate descr");
        assert!(!fd.is_finish());
        assert_eq!(fd.fail_index(), u32::MAX);
        let grabbed = backend.grab_exc_value(&frame).0 as i64;
        assert_eq!(grabbed, exc);
        assert_eq!(
            majit_backend::propagate_exception_handle_fail(fd, grabbed),
            Some(exc)
        );

        jit_exc_clear();
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        let descr = backend.get_latest_descr_arc(&frame);
        let fd = descr.as_fail_descr().expect("propagate descr");
        let grabbed = backend.grab_exc_value(&frame).0 as i64;
        assert_eq!(grabbed, 0);
        // `handle_fail` asserts the fallback is non-null, so the null-cell
        // arm is checked only once some provider is registered.
        if memory_error != 0 {
            assert_eq!(
                majit_backend::propagate_exception_handle_fail(fd, grabbed),
                Some(memory_error)
            );
        }
    }

