    #[test]
    fn publish_merged_entry_redirects_execute_token() {
        let mut backend = CraneliftBackend::new();
        let inputargs_a = vec![InputArg::new_int_rc(0)];
        let label_a = make_label_descr(1);
        let ops_a = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label_a.clone(),
            ),
            mk_op(
                OpCode::Finish,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
            ),
        ];
        let token_a = JitCellToken::new(9102);
        token_a.record_target_token(label_a.clone());
        backend
            .compile_loop(&inputargs_a, &ops_a, &token_a)
            .unwrap();

        let inputargs_b = vec![InputArg::new_int_rc(0)];
        let label_b = make_label_descr(2);
        let ops_b = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label_b,
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::input_arg_int(0)],
                1,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        let token_b = JitCellToken::new(9103);
        backend
            .compile_loop(&inputargs_b, &ops_b, &token_b)
            .unwrap();
        let (b_code, b_body, depth, family_entry) = {
            let compiled_b = token_b
                .compiled
                .get()
                .unwrap()
                .downcast_ref::<CompiledLoop>()
                .unwrap();
            let family_entry = LoopTargetEntry {
                code_ptr: compiled_b.code_ptr,
                fail_descrs: compiled_b.fail_descrs.clone(),
                fail_descr_cells: compiled_b.fail_descr_cells.clone(),
                num_inputs: compiled_b.num_inputs,
                num_ref_roots: compiled_b.num_ref_roots,
                max_output_slots: compiled_b.max_output_slots,
            };
            (
                compiled_b.code_ptr as usize,
                compiled_b.body_ptr as usize,
                compiled_b.frame_depth,
                family_entry,
            )
        };
        let stub_a = token_a.ll_function_addr();
        backend.publish_merged_entry(
            &token_a,
            b_code,
            b_body,
            depth,
            Arc::new(MergedGeneration {
                asm_memory_blocks: Vec::new(),
                gcmap_allocs: Vec::new(),
                fail_descr_cells: Vec::new(),
                gc_table: None,
                cpu_attachments: None,
            }),
            // B's only LABEL is block 0 of B's function.
            &[(label_a.clone(), 0)],
            &[],
            &family_entry,
        );
        let frame = backend.execute_token(&token_a, &[Value::Int(21)]);
        assert_eq!(backend.get_int_value(&frame, 0), 42);
        let target = label_a
            .as_loop_target_descr()
            .expect("LABEL descr is a LoopTargetDescr");
        assert_eq!(target.ll_loop_code(), b_body);
        assert_eq!(token_a.ll_function_addr(), stub_a);
        // `token_b` keeps B's assembler memory alive for the redirected entry.
        let _keep_b = token_b;
    }

    #[test]
    fn publish_merged_entry_keeps_the_stable_door() {
        let mut backend = make_call_assembler_backend();
        let label_a = make_label_descr(1_500_640);
        let label_b = make_label_descr(1_500_641);
        let label_c = make_label_descr(1_500_642);
        let token_a = JitCellToken::new(9110);
        let token_b = JitCellToken::new(9111);
        let token_c = JitCellToken::new(9112);
        compile_int_add_loop(&mut backend, &token_a, &label_a, 1);
        compile_int_add_loop(&mut backend, &token_b, &label_b, 100);
        compile_int_add_loop(&mut backend, &token_c, &label_c, 7);

        let (b_code, b_body, depth, family_entry) = {
            let compiled_b = token_b
                .compiled
                .get()
                .unwrap()
                .downcast_ref::<CompiledLoop>()
                .unwrap();
            let family_entry = LoopTargetEntry {
                code_ptr: compiled_b.code_ptr,
                fail_descrs: compiled_b.fail_descrs.clone(),
                fail_descr_cells: compiled_b.fail_descr_cells.clone(),
                num_inputs: compiled_b.num_inputs,
                num_ref_roots: compiled_b.num_ref_roots,
                max_output_slots: compiled_b.max_output_slots,
            };
            (
                compiled_b.code_ptr as usize,
                compiled_b.body_ptr as usize,
                compiled_b.frame_depth,
                family_entry,
            )
        };
        let stub_b = token_b.ll_function_addr();
        backend.publish_merged_entry(
            &token_b,
            b_code,
            b_body,
            depth,
            Arc::new(MergedGeneration {
                asm_memory_blocks: Vec::new(),
                gcmap_allocs: Vec::new(),
                fail_descr_cells: Vec::new(),
                gc_table: None,
                cpu_attachments: None,
            }),
            &[(label_b.clone(), 0)],
            &[],
            &family_entry,
        );
        assert_eq!(
            crate::stub::follow_jump(stub_b),
            stub_b,
            "merged publish must keep the far-veneer door"
        );

        backend.redirect_call_assembler(&token_a, &token_b).unwrap();
        backend.redirect_call_assembler(&token_b, &token_c).unwrap();
        assert_eq!(
            backend.get_int_value(&backend.execute_token(&token_a, &[Value::Int(0)]), 0),
            7
        );
    }

    fn bind_target_owner(label: &majit_ir::DescrRef, token: &Arc<JitCellToken>) {
        token.record_target_token(label.clone());
        label
            .as_loop_target_descr()
            .unwrap()
            .set_original_jitcell_token_handle(token.clone());
    }

    fn stamp_one_loc(descr: &majit_ir::DescrRef) {
        descr
            .as_fail_descr()
            .unwrap()
            .set_rd_locs(majit_ir::RdLocs::from_vec(vec![0]));
    }

    /// A adds 1 and, on an odd value, bridges to C. C adds 10 and, on an odd
    /// value, bridges back to A. Both exit at `>= 40`. From 0 the crossings
    /// are 1→C, 11→A, 13→C, 23→A, 25→C, 35→A, 37→C, then 47. Staying inside
    /// A yields 40; staying inside C after the first hop yields 41.
    #[test]
    fn family_merge_makes_cross_token_jumps_local() {
        let mut backend = CraneliftBackend::new();
        let inputargs = vec![InputArg::new_int_rc(0)];
        let n = OpRef::input_arg_int(0);

        let label_a = make_label_descr(1_500_410);
        let exit_a = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let odd_a = mk_test_resume_guard_descr(0, vec![Type::Int]);
        stamp_one_loc(&exit_a);
        stamp_one_loc(&odd_a);
        let ops_a = vec![
            mk_op_with_descr(OpCode::Label, &[n], OpRef::NONE.raw(), label_a.clone()),
            mk_op(OpCode::IntAdd, &[n, OpRef::const_int(1)], 1),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(40)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_a,
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_a.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label_a.clone(),
            ),
        ];
        let token_a = Arc::new(JitCellToken::new(1_500_410));
        bind_target_owner(&label_a, &token_a);
        backend.compile_loop(&inputargs, &ops_a, &token_a).unwrap();

        let label_c = make_label_descr(1_500_411);
        let exit_c = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let odd_c = mk_test_resume_guard_descr(0, vec![Type::Int]);
        stamp_one_loc(&exit_c);
        stamp_one_loc(&odd_c);
        let ops_c = vec![
            mk_op_with_descr(OpCode::Label, &[n], OpRef::NONE.raw(), label_c.clone()),
            mk_op(OpCode::IntAdd, &[n, OpRef::const_int(10)], 1),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(40)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_c,
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_c.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label_c.clone(),
            ),
        ];
        let token_c = Arc::new(JitCellToken::new(1_500_411));
        bind_target_owner(&label_c, &token_c);
        backend.compile_loop(&inputargs, &ops_c, &token_c).unwrap();

        let bridge_to_c = vec![mk_op_with_descr(
            OpCode::Jump,
            &[n],
            OpRef::NONE.raw(),
            label_c.clone(),
        )];
        backend
            .compile_bridge(as_fd(&odd_a), &inputargs, &bridge_to_c, &token_a)
            .unwrap();
        let bridge_to_a = vec![mk_op_with_descr(
            OpCode::Jump,
            &[n],
            OpRef::NONE.raw(),
            label_a.clone(),
        )];
        backend
            .compile_bridge(as_fd(&odd_c), &inputargs, &bridge_to_a, &token_c)
            .unwrap();

        let (family_body, family_code) = {
            let compiled_c = token_c
                .compiled
                .get()
                .unwrap()
                .downcast_ref::<CompiledLoop>()
                .unwrap();
            assert_ne!(
                compiled_c.entry_code_ptr.load(Ordering::Acquire),
                compiled_c.code_ptr as usize,
                "C's bridge attach publishes C's family entry"
            );
            (
                compiled_c.entry_body_ptr.load(Ordering::Acquire),
                compiled_c.entry_code_ptr.load(Ordering::Acquire),
            )
        };
        assert_eq!(
            label_a.as_loop_target_descr().unwrap().ll_loop_code(),
            family_body
        );
        let registered = lookup_loop_target(&label_a).expect("A's LABEL stays registered");
        assert_eq!(registered.code_ptr as usize, family_code);

        let frame = backend.execute_token(&token_a, &[Value::Int(0)]);
        assert_eq!(backend.get_int_value(&frame, 0), 47);
    }

    /// Same crossings as `family_merge_makes_cross_token_jumps_local`, but C
    /// runs a preamble before its LABEL, the shape an unrolled loop has. The
    /// family JUMP enters C at the LABEL, so C still joins the family and
    /// the result is 47, not the 40 of staying inside A.
    #[test]
    fn family_member_with_a_preamble_joins_at_its_label() {
        let mut backend = CraneliftBackend::new();
        let inputargs = vec![InputArg::new_int_rc(0)];
        let n = OpRef::input_arg_int(0);

        let label_a = make_label_descr(1_500_430);
        let exit_a = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let odd_a = mk_test_resume_guard_descr(0, vec![Type::Int]);
        stamp_one_loc(&exit_a);
        stamp_one_loc(&odd_a);
        let ops_a = vec![
            mk_op_with_descr(OpCode::Label, &[n], OpRef::NONE.raw(), label_a.clone()),
            mk_op(OpCode::IntAdd, &[n, OpRef::const_int(1)], 1),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(40)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_a,
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_a.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label_a.clone(),
            ),
        ];
        let token_a = Arc::new(JitCellToken::new(1_500_430));
        bind_target_owner(&label_a, &token_a);
        backend.compile_loop(&inputargs, &ops_a, &token_a).unwrap();

        let label_c = make_label_descr(1_500_431);
        let exit_c = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let odd_c = mk_test_resume_guard_descr(0, vec![Type::Int]);
        stamp_one_loc(&exit_c);
        stamp_one_loc(&odd_c);
        let ops_c = vec![
            mk_op(OpCode::IntAdd, &[n, OpRef::const_int(0)], 5),
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::int_op(5)],
                OpRef::NONE.raw(),
                label_c.clone(),
            ),
            mk_op(OpCode::IntAdd, &[OpRef::int_op(5), OpRef::const_int(10)], 1),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(40)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_c,
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_c.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label_c.clone(),
            ),
        ];
        let token_c = Arc::new(JitCellToken::new(1_500_431));
        bind_target_owner(&label_c, &token_c);
        backend.compile_loop(&inputargs, &ops_c, &token_c).unwrap();

        let bridge_to_c = vec![mk_op_with_descr(
            OpCode::Jump,
            &[n],
            OpRef::NONE.raw(),
            label_c.clone(),
        )];
        backend
            .compile_bridge(as_fd(&odd_a), &inputargs, &bridge_to_c, &token_a)
            .unwrap();
        let bridge_to_a = vec![mk_op_with_descr(
            OpCode::Jump,
            &[n],
            OpRef::NONE.raw(),
            label_a.clone(),
        )];
        backend
            .compile_bridge(as_fd(&odd_c), &inputargs, &bridge_to_a, &token_c)
            .unwrap();

        let family_body = token_c
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_body_ptr
            .load(Ordering::Acquire);
        assert_eq!(
            label_a.as_loop_target_descr().unwrap().ll_loop_code(),
            family_body,
            "A's LABEL points into the function that merged C"
        );
        let frame = backend.execute_token(&token_a, &[Value::Int(0)]);
        assert_eq!(backend.get_int_value(&frame, 0), 47);
    }

    /// A read after the member's first LABEL of a value only its preamble
    /// defines cannot be carried into the merged function.
    #[test]
    fn member_entry_args_refuse_a_read_of_a_preamble_value() {
        let n = OpRef::input_arg_int(0);
        let label = make_label_descr(1_500_440);
        let closed = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::int_op(5)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(OpCode::IntAdd, &[OpRef::int_op(5), OpRef::const_int(1)], 1),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let closed: Vec<Op> = closed.iter().map(|op| snapshot_op(op)).collect();
        assert_eq!(member_entry_args(&closed), Some(vec![OpRef::int_op(5)]));
        let leaking = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::int_op(5)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(OpCode::IntAdd, &[OpRef::int_op(5), OpRef::int_op(6)], 1),
            mk_op_with_descr(OpCode::Jump, &[n], OpRef::NONE.raw(), label),
        ];
        let leaking: Vec<Op> = leaking.iter().map(|op| snapshot_op(op)).collect();
        assert_eq!(member_entry_args(&leaking), None);
    }

    /// C's `GuardNotInvalidated` must load C's flag. Invalidating C exits a
    /// path that reaches C, and leaves a path that stays in A alone.
    #[test]
    fn family_member_guard_not_invalidated_reads_member_flag() {
        let mut backend = CraneliftBackend::new();
        let inputargs = vec![InputArg::new_int_rc(0)];
        let n = OpRef::input_arg_int(0);

        let label_a = make_label_descr(1_500_420);
        let to_c = mk_test_resume_guard_descr(0, vec![Type::Int]);
        stamp_one_loc(&to_c);
        let ops_a = vec![
            mk_op_with_descr(OpCode::Label, &[n], OpRef::NONE.raw(), label_a.clone()),
            mk_op(OpCode::IntEq, &[n, OpRef::const_int(0)], 1),
            guard_op(OpCode::GuardTrue, OpRef::int_op(1), n, 10, to_c.clone()),
            mk_op(OpCode::Finish, &[n], OpRef::NONE.raw()),
        ];
        let token_a = Arc::new(JitCellToken::new(1_500_420));
        bind_target_owner(&label_a, &token_a);
        backend.compile_loop(&inputargs, &ops_a, &token_a).unwrap();

        let label_c = make_label_descr(1_500_421);
        let inv = mk_test_resume_guard_descr(0, vec![Type::Int]);
        stamp_one_loc(&inv);
        let inv_op = Op::with_descr(OpCode::GuardNotInvalidated, &[], inv.clone());
        inv_op.pos().set(OpRef::void_op(10));
        inv_op.set_fail_arg_types(vec![Type::Int]);
        inv_op.setfailargs(smallvec::smallvec![rb(n)]);
        let ops_c = vec![
            mk_op_with_descr(OpCode::Label, &[n], OpRef::NONE.raw(), label_c.clone()),
            OpRc::new(inv_op),
            mk_op(OpCode::IntAdd, &[n, OpRef::const_int(1)], 1),
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        let token_c = Arc::new(JitCellToken::new(1_500_421));
        bind_target_owner(&label_c, &token_c);
        backend.compile_loop(&inputargs, &ops_c, &token_c).unwrap();

        let bridge = vec![mk_op_with_descr(
            OpCode::Jump,
            &[n],
            OpRef::NONE.raw(),
            label_c.clone(),
        )];
        backend
            .compile_bridge(as_fd(&to_c), &inputargs, &bridge, &token_a)
            .unwrap();
        {
            let compiled_a = token_a
                .compiled
                .get()
                .unwrap()
                .downcast_ref::<CompiledLoop>()
                .unwrap();
            assert_ne!(
                compiled_a.entry_code_ptr.load(Ordering::Acquire),
                compiled_a.code_ptr as usize
            );
            assert_eq!(
                label_c.as_loop_target_descr().unwrap().ll_loop_code(),
                compiled_a.entry_body_ptr.load(Ordering::Acquire)
            );
        }

        let crossed = backend.execute_token(&token_a, &[Value::Int(1)]);
        assert!(backend.get_latest_descr(&crossed).is_finish());
        assert_eq!(backend.get_int_value(&crossed, 0), 2);

        token_c.invalidate();
        let stayed = backend.execute_token(&token_a, &[Value::Int(0)]);
        assert!(backend.get_latest_descr(&stayed).is_finish());
        assert_eq!(backend.get_int_value(&stayed, 0), 0);
        assert!(!Arc::ptr_eq(&backend.get_latest_descr_arc(&stayed), &inv));

        let reached = backend.execute_token(&token_a, &[Value::Int(1)]);
        assert!(Arc::ptr_eq(&backend.get_latest_descr_arc(&reached), &inv));
        assert_eq!(backend.get_int_value(&reached, 0), 1);
    }

    /// A JUMP at a loop compiled with a constants pool has no merge source, so
    /// it stays a dispatch out of L. L's own bridge still publishes a merge.
    #[test]
    fn jump_to_loop_without_merge_source_stays_external() {
        let mut backend = CraneliftBackend::new();
        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(50, 7);
        backend.set_constants(constants);

        let inputargs = vec![InputArg::new_int_rc(0)];
        let n = OpRef::input_arg_int(0);
        let label_t = make_label_descr(1_500_430);
        let ops_t = vec![
            mk_op_with_descr(OpCode::Label, &[n], OpRef::NONE.raw(), label_t.clone()),
            mk_op(OpCode::IntAdd, &[n, OpRef::int_op(50)], 1),
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        let token_t = Arc::new(JitCellToken::new(1_500_430));
        bind_target_owner(&label_t, &token_t);
        backend.compile_loop(&inputargs, &ops_t, &token_t).unwrap();
        {
            let compiled_t = token_t
                .compiled
                .get()
                .unwrap()
                .downcast_ref::<CompiledLoop>()
                .unwrap();
            assert!(compiled_t.merge_source.is_none());
        }

        let label_l = make_label_descr(1_500_431);
        let to_t = mk_test_resume_guard_descr(0, vec![Type::Int]);
        stamp_one_loc(&to_t);
        let ops_l = vec![
            mk_op_with_descr(OpCode::Label, &[n], OpRef::NONE.raw(), label_l.clone()),
            mk_op(OpCode::IntLt, &[n, OpRef::const_int(0)], 1),
            guard_op(OpCode::GuardTrue, OpRef::int_op(1), n, 10, to_t.clone()),
            mk_op(OpCode::Finish, &[n], OpRef::NONE.raw()),
        ];
        let token_l = Arc::new(JitCellToken::new(1_500_431));
        bind_target_owner(&label_l, &token_l);
        backend.compile_loop(&inputargs, &ops_l, &token_l).unwrap();

        let bridge = vec![mk_op_with_descr(
            OpCode::Jump,
            &[n],
            OpRef::NONE.raw(),
            label_t.clone(),
        )];
        backend
            .compile_bridge(as_fd(&to_t), &inputargs, &bridge, &token_l)
            .unwrap();
        {
            let compiled_l = token_l
                .compiled
                .get()
                .unwrap()
                .downcast_ref::<CompiledLoop>()
                .unwrap();
            assert_ne!(
                compiled_l.entry_code_ptr.load(Ordering::Acquire),
                compiled_l.code_ptr as usize,
                "L's merge still publishes"
            );
            assert_ne!(
                label_t.as_loop_target_descr().unwrap().ll_loop_code(),
                compiled_l.entry_body_ptr.load(Ordering::Acquire),
                "T was not pulled into L's family"
            );
        }
        let frame = backend.execute_token(&token_l, &[Value::Int(4)]);
        assert!(backend.get_latest_descr(&frame).is_finish());
        assert_eq!(backend.get_int_value(&frame, 0), 11);
    }

    /// Every loop numbers its LABEL descrs from the same small token ids, so
    /// a JUMP to another loop's LABEL can carry the same `Descr::index` and
    /// arity as a LABEL of the loop being compiled. It still leaves the loop.
    #[test]
    fn jump_to_other_loops_label_with_same_index_is_external() {
        let mut backend = CraneliftBackend::new();
        let inputargs = vec![InputArg::new_int_rc(0)];
        let label_a = make_label_descr(1);
        let ops_a = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label_a.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        let token_a = JitCellToken::new(9104);
        token_a.record_target_token(label_a.clone());
        backend.compile_loop(&inputargs, &ops_a, &token_a).unwrap();

        let label_b = make_label_descr(1);
        assert_eq!(label_a.index(), label_b.index());
        let guard = mk_op(OpCode::GuardTrue, &[OpRef::int_op(2)], OpRef::NONE.raw());
        guard.setfailargs(smallvec::smallvec![rb(OpRef::int_op(1))]);
        let ops_b = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label_b.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(100)],
                1,
            ),
            mk_op(
                OpCode::IntLt,
                &[OpRef::int_op(1), OpRef::const_int(1000)],
                2,
            ),
            guard,
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label_a,
            ),
        ];
        let token_b = JitCellToken::new(9105);
        token_b.record_target_token(label_b);
        backend.compile_loop(&inputargs, &ops_b, &token_b).unwrap();

        // B adds 100 once and jumps into A, which adds 1 and finishes. Looping
        // back to B's own LABEL would instead add 100 until the guard fails.
        let frame = backend.execute_token(&token_b, &[Value::Int(0)]);
        assert!(backend.get_latest_descr(&frame).is_finish());
        assert_eq!(backend.get_int_value(&frame, 0), 101);
        let _keep_a = token_a;
    }

    /// Simple-loop TargetTokens all carry `Descr::index` 0. Type-propagation
    /// and block lookup must still treat a JUMP to a *different* index-0
    /// object as an external edge (`x86/regalloc.py consider_jump`,
    /// `x86/assembler.py closing_jump` / `fixup_target_tokens`).
    #[test]
    fn jump_to_distinct_index_0_target_is_not_local_back_edge() {
        let mut backend = CraneliftBackend::new();
        let inputargs = vec![InputArg::new_int_rc(0)];
        let label_a = make_label_descr(0);
        let ops_a = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label_a.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        let token_a = JitCellToken::new(9106);
        token_a.record_target_token(label_a.clone());
        backend.compile_loop(&inputargs, &ops_a, &token_a).unwrap();

        let label_b = make_label_descr(0);
        assert_eq!(label_a.index(), 0);
        assert_eq!(label_b.index(), 0);
        assert_ne!(
            majit_ir::descr_identity(&label_a),
            majit_ir::descr_identity(&label_b)
        );
        let guard = mk_op(OpCode::GuardTrue, &[OpRef::int_op(2)], OpRef::NONE.raw());
        guard.setfailargs(smallvec::smallvec![rb(OpRef::int_op(1))]);
        let ops_b = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label_b.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(100)],
                1,
            ),
            mk_op(
                OpCode::IntLt,
                &[OpRef::int_op(1), OpRef::const_int(1000)],
                2,
            ),
            guard,
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label_a,
            ),
        ];
        let token_b = JitCellToken::new(9107);
        token_b.record_target_token(label_b);
        backend.compile_loop(&inputargs, &ops_b, &token_b).unwrap();

        // B adds 100 once and jumps into A. Matching on `Descr::index` 0
        // would treat that JUMP as B's own back-edge and add 100 until the
        // guard fails.
        let frame = backend.execute_token(&token_b, &[Value::Int(0)]);
        assert!(backend.get_latest_descr(&frame).is_finish());
        assert_eq!(backend.get_int_value(&frame, 0), 101);
        let _keep_a = token_a;
    }

    fn guard_op(
        opcode: OpCode,
        arg: OpRef,
        fail: OpRef,
        pos: u32,
        descr: majit_ir::DescrRef,
    ) -> OpRc {
        let op = Op::with_descr(opcode, &[rb(arg)], descr);
        op.pos().set(OpRef::void_op(pos));
        op.set_fail_arg_types(vec![Type::Int]);
        op.setfailargs(smallvec::smallvec![rb(fail)]);
        OpRc::new(op)
    }

    #[test]
    fn merged_bridge_jump_keeps_the_loop_exit() {
        let mut backend = CraneliftBackend::new();
        let label = make_label_descr(11);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        exit_descr
            .as_fail_descr()
            .unwrap()
            .set_rd_locs(majit_ir::RdLocs::from_vec(vec![0]));
        let odd_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        odd_descr
            .as_fail_descr()
            .unwrap()
            .set_rd_locs(majit_ir::RdLocs::from_vec(vec![0]));
        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(100)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_descr.clone(),
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_descr.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9200);
        token.record_target_token(label.clone());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let before = backend.execute_token(&token, &[Value::Int(0)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&before),
            &odd_descr
        ));
        assert_eq!(backend.get_int_value(&before, 0), 1);
        let entry_before = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);

        let bridge_inputargs = vec![InputArg::new_int_rc(0)];
        let bridge_ops = vec![
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(10)],
                1,
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        backend
            .compile_bridge(as_fd(&odd_descr), &bridge_inputargs, &bridge_ops, &token)
            .unwrap();
        let entry_after = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        assert_ne!(entry_before, entry_after);
        let after = backend.execute_token(&token, &[Value::Int(0)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&after),
            &exit_descr
        ));
        assert_eq!(backend.get_int_value(&after, 0), 108);
    }

    #[test]
    fn merged_bridge_survives_rewrite_inserted_before_the_bridge() {
        // An allocation after the source guard makes the GC rewrite insert
        // ops in the loop tail. The bridge's post-rewrite start must still
        // be the failure edge, and the loop must exit at 108.
        let mut backend = CraneliftBackend::new();
        let label = make_label_descr(14);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        exit_descr
            .as_fail_descr()
            .unwrap()
            .set_rd_locs(majit_ir::RdLocs::from_vec(vec![0]));
        let odd_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        odd_descr
            .as_fail_descr()
            .unwrap()
            .set_rd_locs(majit_ir::RdLocs::from_vec(vec![0]));
        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(100)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_descr.clone(),
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_descr.clone(),
            ),
            mk_op_with_descr(OpCode::New, &[], 4, make_size_descr(16, 14)),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9204);
        token.record_target_token(label.clone());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let bridge_inputargs = vec![InputArg::new_int_rc(0)];
        let bridge_ops = vec![
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(10)],
                1,
            ),
            mk_op_with_descr(OpCode::Jump, &[OpRef::int_op(1)], OpRef::NONE.raw(), label),
        ];
        backend
            .compile_bridge(as_fd(&odd_descr), &bridge_inputargs, &bridge_ops, &token)
            .unwrap();
        {
            let entry = token
                .compiled
                .get()
                .unwrap()
                .downcast_ref::<CompiledLoop>()
                .unwrap();
            assert_ne!(
                entry.entry_code_ptr.load(Ordering::Acquire),
                entry.code_ptr as usize
            );
        }
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&frame),
            &exit_descr
        ));
        assert_eq!(backend.get_int_value(&frame, 0), 108);
    }

    #[test]
    fn merged_bridge_guard_returns_its_own_descr() {
        let mut backend = CraneliftBackend::new();
        let label = make_label_descr(12);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        exit_descr
            .as_fail_descr()
            .unwrap()
            .set_rd_locs(majit_ir::RdLocs::from_vec(vec![0]));
        let odd_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        odd_descr
            .as_fail_descr()
            .unwrap()
            .set_rd_locs(majit_ir::RdLocs::from_vec(vec![0]));
        let bridge_guard_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        bridge_guard_descr
            .as_fail_descr()
            .unwrap()
            .set_rd_locs(majit_ir::RdLocs::from_vec(vec![0]));
        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(100)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_descr.clone(),
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_descr.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9201);
        token.record_target_token(label.clone());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let bridge_inputargs = vec![InputArg::new_int_rc(0)];
        let bridge_ops = vec![
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(10)],
                1,
            ),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(1),
                OpRef::int_op(1),
                4,
                bridge_guard_descr.clone(),
            ),
            // The guard fails on this input. The success edge still needs a
            // terminator; an empty continuation block is not a valid function.
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        backend
            .compile_bridge(as_fd(&odd_descr), &bridge_inputargs, &bridge_ops, &token)
            .unwrap();
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&frame),
            &bridge_guard_descr
        ));
        assert_eq!(backend.get_int_value(&frame, 0), 11);

        // A bridge attached to the spliced bridge's guard is spliced too:
        // the attach republishes the loop entry.
        let entry_code_ptr = || {
            token
                .compiled
                .get()
                .unwrap()
                .downcast_ref::<CompiledLoop>()
                .unwrap()
                .entry_code_ptr
                .load(Ordering::Acquire)
        };
        let entry_before = entry_code_ptr();
        let nested_ops = vec![
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(100)],
                1,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        backend
            .compile_bridge(
                as_fd(&bridge_guard_descr),
                &[InputArg::new_int_rc(0)],
                &nested_ops,
                &token,
            )
            .unwrap();
        assert_ne!(entry_before, entry_code_ptr());
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        assert!(backend.get_latest_descr(&frame).is_finish());
        assert_eq!(backend.get_int_value(&frame, 0), 111);
    }

    /// A merged recompile re-emits a guard without a bridge through the
    /// trampoline its descr already names, so one `patch_jump_for_descr`
    /// redirects every copy. A re-emitted guard whose own bridge is already
    /// attached gets a trampoline that starts patched to that bridge, and
    /// `adr_jump_offset` stays cleared.
    #[test]
    fn merged_recompile_keeps_attached_bridge_patched() {
        let mut backend = CraneliftBackend::new();
        let label = make_label_descr(14);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let odd_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let bridge_guard_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(100)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_descr.clone(),
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_descr.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9202);
        token.record_target_token(label.clone());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let exit_stub = as_fd(&exit_descr).adr_jump_offset();
        assert_ne!(exit_stub, 0);
        let finish_plus = |n: i64| {
            vec![
                mk_op(
                    OpCode::IntAdd,
                    &[OpRef::input_arg_int(0), OpRef::const_int(n)],
                    1,
                ),
                mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
            ]
        };
        let odd_bridge = vec![
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(10)],
                1,
            ),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(1),
                OpRef::int_op(1),
                4,
                bridge_guard_descr.clone(),
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        backend
            .compile_bridge(
                as_fd(&odd_descr),
                &[InputArg::new_int_rc(0)],
                &odd_bridge,
                &token,
            )
            .unwrap();
        assert_eq!(as_fd(&exit_descr).adr_jump_offset(), exit_stub);
        // Attached to a guard of the spliced bridge: not itself spliced.
        backend
            .compile_bridge(
                as_fd(&bridge_guard_descr),
                &[InputArg::new_int_rc(0)],
                &finish_plus(100),
                &token,
            )
            .unwrap();
        assert_eq!(as_fd(&bridge_guard_descr).adr_jump_offset(), 0);
        // Another loop bridge re-emits the odd bridge in a new generation.
        backend
            .compile_bridge(
                as_fd(&exit_descr),
                &[InputArg::new_int_rc(0)],
                &finish_plus(1000),
                &token,
            )
            .unwrap();
        assert_eq!(as_fd(&bridge_guard_descr).adr_jump_offset(), 0);
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        assert_eq!(backend.get_int_value(&frame, 0), 111);
    }

    /// A merged recompile does not stamp `make_a_counter_per_value` again, so
    /// a GUARD_VALUE parks its operand in the slot the original compile put
    /// in the status, even when a spliced bridge widens the value area.
    #[test]
    fn merged_guard_value_parks_its_operand_in_the_stamped_slot() {
        let mut backend = CraneliftBackend::new();
        let label = make_label_descr(15);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let odd_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let value_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let wide_descr = mk_test_resume_guard_descr(0, vec![Type::Int; 3]);
        let inputargs = vec![InputArg::new_int_rc(0)];
        let value_guard = Op::with_descr(
            OpCode::GuardValue,
            &[rb(OpRef::int_op(4)), rb(OpRef::const_int(1000))],
            value_descr.clone(),
        );
        value_guard.pos().set(OpRef::void_op(12));
        value_guard.set_fail_arg_types(vec![Type::Int]);
        value_guard.setfailargs(smallvec::smallvec![rb(OpRef::int_op(1))]);
        let ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(100)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_descr,
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_descr.clone(),
            ),
            mk_op(OpCode::IntAdd, &[OpRef::int_op(1), OpRef::const_int(7)], 4),
            OpRc::new(value_guard),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9203);
        token.record_target_token(label.clone());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        // The bridge's three fail args widen the merged value area past the
        // loop's own counter slot.
        let wide_guard = Op::with_descr(
            OpCode::GuardFalse,
            &[rb(OpRef::int_op(2))],
            wide_descr.clone(),
        );
        wide_guard.pos().set(OpRef::void_op(3));
        wide_guard.set_fail_arg_types(vec![Type::Int; 3]);
        wide_guard.setfailargs(smallvec::smallvec![
            rb(OpRef::input_arg_int(0)),
            rb(OpRef::int_op(1)),
            rb(OpRef::input_arg_int(0)),
        ]);
        let odd_bridge = vec![
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(
                OpCode::IntGt,
                &[OpRef::int_op(1), OpRef::const_int(1000)],
                2,
            ),
            OpRc::new(wide_guard),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label,
            ),
        ];
        let entry_before = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        backend
            .compile_bridge(
                as_fd(&odd_descr),
                &[InputArg::new_int_rc(0)],
                &odd_bridge,
                &token,
            )
            .unwrap();
        let entry_after = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        assert_ne!(entry_before, entry_after, "the bridge is spliced");
        // 0 -> 1 is odd and takes the bridge, which jumps back with 1. Then
        // 1 -> 2 reaches the GUARD_VALUE with 2 + 7.
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&frame),
            &value_descr
        ));
        let slot = majit_backend::guard_value_counter_slot(as_fd(&value_descr))
            .expect("the GUARD_VALUE stamped a counter slot");
        assert_eq!(backend.get_value_direct(&frame, slot), 9);
    }

    #[test]
    fn merged_exit_honours_redirected_rd_locs() {
        let _const_ptr_guard = const_ptr_gc_test_guard();
        // The carried ref is deopt-only, so `compute_loop_phi_keep` demotes
        // it and `apply_resident_failarg_locs` points `rd_locs` at that home.
        // A nursery allocation before the guard forwards the home. The merged
        // exit must publish that word, not the positional slot.
        let mut gc = MiniMarkGC::with_config(GcConfig {
            nursery_size: 160,
            large_object_threshold: 1024,
            ..GcConfig::default()
        });
        gc.register_type(TypeInfo::simple(16));
        let root = gc.alloc_with_type(0, 16);
        unsafe {
            *(root.0 as *mut u64) = 0xD30F_00C1;
        }
        let mut backend = backend_with_gc(gc);
        let label = make_label_descr(15);
        // Raw 1 is the int input's index. A ref at that raw is treated as an
        // input and is not demoted, so the carried box sits above the inputs.
        let carried = OpRef::ref_op(8);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Ref]);
        let odd_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let exit = Op::with_descr(
            OpCode::GuardTrue,
            &[rb(OpRef::int_op(3))],
            exit_descr.clone(),
        );
        exit.pos().set(OpRef::void_op(10));
        exit.set_fail_arg_types(vec![Type::Ref]);
        exit.setfailargs(smallvec::smallvec![rb(carried)]);
        let odd = Op::with_descr(
            OpCode::GuardFalse,
            &[rb(OpRef::int_op(4))],
            odd_descr.clone(),
        );
        odd.pos().set(OpRef::void_op(11));
        odd.set_fail_arg_types(vec![Type::Int]);
        odd.setfailargs(smallvec::smallvec![rb(OpRef::int_op(2))]);
        let inputargs = vec![InputArg::new_ref_rc(0), InputArg::new_int_rc(1)];
        let ops = vec![
            mk_op(OpCode::SameAsR, &[OpRef::input_arg_ref(0)], carried.raw()),
            mk_op_with_descr(
                OpCode::Label,
                &[carried, OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(OpCode::CallMallocNursery, &[OpRef::const_int(256)], 6),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(1), OpRef::const_int(1)],
                2,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(2), OpRef::const_int(100)], 3),
            OpRc::new(exit),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(2), OpRef::const_int(1)], 4),
            OpRc::new(odd),
            mk_op_with_descr(
                OpCode::Jump,
                &[carried, OpRef::int_op(2)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9205);
        token.record_target_token(label.clone());
        backend.set_constants(indexmap::IndexMap::new());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let locs = exit_descr.as_fail_descr().unwrap().rd_locs();
        assert!(
            !locs.is_empty() && locs[0] != 0 && locs[0] != 0xFFFF,
            "original compile should redirect the demoted ref, got {locs:?}"
        );
        let entry_before = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        let bridge_ops = vec![
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(10)],
                1,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        backend
            .compile_bridge(
                as_fd(&odd_descr),
                &[InputArg::new_int_rc(0)],
                &bridge_ops,
                &token,
            )
            .unwrap();
        let entry_after = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        assert_ne!(entry_before, entry_after);
        let frame = backend.execute_token(&token, &[Value::Ref(root), Value::Int(99)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&frame),
            &exit_descr
        ));
        let moved = backend.get_ref_value(&frame, 0);
        assert_ne!(moved, root);
        assert_eq!(unsafe { *(moved.0 as *const u64) }, 0xD30F_00C1);
    }

    #[test]
    fn merged_bridge_from_before_the_label_seeds_its_demoted_home() {
        // `i0` is loop-invariant and deopt-only, so the loop LABEL demotes it
        // to a frame home that its fall-through seeds. The merged bridge of
        // the guard ahead of that LABEL enters the loop without passing the
        // fall-through; the loop exit must still report `i0`.
        let mut backend = CraneliftBackend::new();
        let label = make_label_descr(16);
        let pre_descr = mk_test_resume_guard_descr(0, vec![Type::Int, Type::Int]);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Int, Type::Int]);
        let pre = Op::with_descr(
            OpCode::GuardTrue,
            &[rb(OpRef::int_op(2))],
            pre_descr.clone(),
        );
        pre.pos().set(OpRef::void_op(10));
        pre.set_fail_arg_types(vec![Type::Int, Type::Int]);
        pre.setfailargs(smallvec::smallvec![
            rb(OpRef::input_arg_int(0)),
            rb(OpRef::input_arg_int(1))
        ]);
        let exit = Op::with_descr(
            OpCode::GuardTrue,
            &[rb(OpRef::int_op(4))],
            exit_descr.clone(),
        );
        exit.pos().set(OpRef::void_op(11));
        exit.set_fail_arg_types(vec![Type::Int, Type::Int]);
        exit.setfailargs(smallvec::smallvec![
            rb(OpRef::input_arg_int(0)),
            rb(OpRef::int_op(3))
        ]);
        let inputargs = vec![InputArg::new_int_rc(0), InputArg::new_int_rc(1)];
        let ops = vec![
            mk_op(
                OpCode::IntLt,
                &[OpRef::input_arg_int(1), OpRef::const_int(1000)],
                2,
            ),
            OpRc::new(pre),
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0), OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(1), OpRef::const_int(1)],
                3,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(3), OpRef::const_int(100)], 4),
            OpRc::new(exit),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::input_arg_int(0), OpRef::int_op(3)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9206);
        token.record_target_token(label.clone());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let before = backend.execute_token(&token, &[Value::Int(42), Value::Int(1000)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&before),
            &pre_descr
        ));
        let entry_before = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        let bridge_ops = vec![
            mk_op(
                OpCode::IntSub,
                &[OpRef::input_arg_int(1), OpRef::const_int(1000)],
                2,
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::input_arg_int(0), OpRef::int_op(2)],
                OpRef::NONE.raw(),
                label,
            ),
        ];
        backend
            .compile_bridge(
                as_fd(&pre_descr),
                &[InputArg::new_int_rc(0), InputArg::new_int_rc(1)],
                &bridge_ops,
                &token,
            )
            .unwrap();
        let entry_after = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        assert_ne!(entry_before, entry_after);
        let frame = backend.execute_token(&token, &[Value::Int(42), Value::Int(1000)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&frame),
            &exit_descr
        ));
        assert_eq!(backend.get_int_value(&frame, 0), 42);
        assert_eq!(backend.get_int_value(&frame, 1), 100);
    }

    /// The bridge body contains `GuardNoException` and the source is
    /// `GuardFalse`, so `collect_merged_bridges` leaves the edge on
    /// `emit_guard_exit`. The separate bridge still runs.
    #[test]
    fn guard_no_exception_inside_bridge_stays_separate() {
        let mut backend = CraneliftBackend::new();
        let label = make_label_descr(16);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let odd_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(100)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_descr.clone(),
            ),
            mk_op(OpCode::IntAnd, &[OpRef::int_op(1), OpRef::const_int(1)], 3),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(3),
                OpRef::int_op(1),
                11,
                odd_descr.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9206);
        token.record_target_token(label.clone());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let entry_before = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        // Source is `GuardFalse`. `GuardNoException` in the bridge body keeps
        // this edge on `emit_guard_exit`.
        let bridge_ops = vec![
            mk_op(OpCode::GuardNoException, &[], OpRef::NONE.raw()),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(10)],
                1,
            ),
            mk_op_with_descr(OpCode::Jump, &[OpRef::int_op(1)], OpRef::NONE.raw(), label),
        ];
        backend
            .compile_bridge(
                as_fd(&odd_descr),
                &[InputArg::new_int_rc(0)],
                &bridge_ops,
                &token,
            )
            .unwrap();
        let entry_after = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        assert_eq!(entry_before, entry_after);
        assert!(fail_descr_bridge_ref(as_fd(&odd_descr)).is_some());
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&frame),
            &exit_descr
        ));
        assert_eq!(backend.get_int_value(&frame, 0), 108);
    }

    /// A loop that contains `GuardNoException` leaves every failure edge
    /// except `GuardNoOverflow` on `emit_guard_exit`. The `GuardNoException`
    /// source and a later `GuardFalse` bridge both keep `entry_code_ptr`.
    /// Execution still reaches the exit through the separate bridge.
    #[test]
    fn guard_no_exception_source_bridge_stays_separate() {
        let mut backend = CraneliftBackend::new();
        let label = make_label_descr(17);
        let exit_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let exc_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let hot_descr = mk_test_resume_guard_descr(0, vec![Type::Int]);
        let noexc = Op::with_descr(OpCode::GuardNoException, &[], exc_descr.clone());
        noexc.pos().set(OpRef::void_op(12));
        noexc.set_fail_arg_types(vec![Type::Int]);
        noexc.setfailargs(smallvec::smallvec![rb(OpRef::input_arg_int(0))]);
        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
            OpRc::new(noexc),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::const_int(1)],
                1,
            ),
            mk_op(OpCode::IntLt, &[OpRef::int_op(1), OpRef::const_int(3)], 2),
            guard_op(
                OpCode::GuardTrue,
                OpRef::int_op(2),
                OpRef::int_op(1),
                10,
                exit_descr.clone(),
            ),
            guard_op(
                OpCode::GuardFalse,
                OpRef::int_op(2),
                OpRef::int_op(1),
                11,
                hot_descr.clone(),
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                label.clone(),
            ),
        ];
        let token = JitCellToken::new(9207);
        token.record_target_token(label.clone());
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let entry_loop = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        let exc_bridge = vec![mk_op_with_descr(
            OpCode::Jump,
            &[OpRef::input_arg_int(0)],
            OpRef::NONE.raw(),
            label.clone(),
        )];
        backend
            .compile_bridge(
                as_fd(&exc_descr),
                &[InputArg::new_int_rc(0)],
                &exc_bridge,
                &token,
            )
            .unwrap();
        let entry_after_exc = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        assert_eq!(entry_loop, entry_after_exc);
        assert!(fail_descr_bridge_ref(as_fd(&exc_descr)).is_some());
        let hot_bridge = vec![
            mk_op(OpCode::GuardNoException, &[], OpRef::NONE.raw()),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                label,
            ),
        ];
        backend
            .compile_bridge(
                as_fd(&hot_descr),
                &[InputArg::new_int_rc(0)],
                &hot_bridge,
                &token,
            )
            .unwrap();
        let entry_after_hot = token
            .compiled
            .get()
            .unwrap()
            .downcast_ref::<CompiledLoop>()
            .unwrap()
            .entry_code_ptr
            .load(Ordering::Acquire);
        assert_eq!(entry_after_exc, entry_after_hot);
        assert!(fail_descr_bridge_ref(as_fd(&hot_descr)).is_some());
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        assert!(Arc::ptr_eq(
            &backend.get_latest_descr_arc(&frame),
            &exit_descr
        ));
        assert_eq!(backend.get_int_value(&frame, 0), 3);
    }

    /// A loop that contains `GuardNoException` still splices a
