    #[test]
    fn test_execute_token_ints_raw_preserves_exception_and_layout_metadata() {
        let _exception_guard = exception_test_guard();
        jit_exc_clear();
        clear_test_exception_call_log();
        set_test_exception_state(make_fake_exc(0x1111));

        let mut backend = CraneliftBackend::new();
        let descr = make_call_descr(vec![Type::Int], Type::Void);

        let inputargs = vec![InputArg::new_int_rc(0)];
        let guard = mk_op(OpCode::GuardNoException, &[], OpRef::NONE.raw());
        guard.setfailargs(smallvec::smallvec![rb(OpRef::input_arg_int(0))]);
        let ops = vec![
            mk_op(OpCode::Label, &[OpRef::input_arg_int(0)], OpRef::NONE.raw()),
            mk_op_with_descr(
                OpCode::CallN,
                &[OpRef::int_op(100), OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                descr,
            ),
            guard,
            mk_op(
                OpCode::Finish,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
            ),
        ];

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(100, maybe_raise_test_exception as *const () as i64);
        backend.set_constants(constants);

        let token = JitCellToken::new(27_001);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let raw = backend.execute_token_ints_raw(&token, &[1]);
        assert!(!raw.is_finish);
        assert_eq!(raw.fail_index, 0);
        assert_eq!(raw.outputs, vec![1]);
        assert_eq!(raw.typed_outputs, vec![Value::Int(1)]);
        assert_eq!(raw.savedata, None);
        // pyjitpl.py raise_if_successful: exc_class = ptr2int(exception_obj.typeptr)
        assert!(!raw.exception_value.is_null());
        assert_eq!(unsafe { *(raw.exception_value.0 as *const i64) }, 0x1111);
        let fd = raw
            .descr_arc
            .as_fail_descr()
            .expect("raw exit carries a FailDescr");
        assert_eq!(fd.fail_index(), 0);
        assert_eq!(fd.source_op_index(), Some(2));
        assert!(!jit_exc_is_pending());
    }

