    #[test]
    fn test_cond_call_value_i_nonzero() {
        static mut COND_CALL_VALUE_CALLS: i64 = 0;

        extern "C" fn compute(a: i64) -> i64 {
            unsafe {
                COND_CALL_VALUE_CALLS += 1;
            }
            a * 10
        }

        unsafe {
            COND_CALL_VALUE_CALLS = 0;
        }

        let mut backend = CraneliftBackend::new();
        let descr = make_call_descr(vec![Type::Int], Type::Int);

        let inputargs = vec![InputArg::new_int_rc(0), InputArg::new_int_rc(1)];
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_int(0), OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
            ),
            mk_op_with_descr(
                OpCode::CondCallValueI,
                &[
                    OpRef::input_arg_int(0),
                    OpRef::int_op(100),
                    OpRef::input_arg_int(1),
                ],
                2,
                descr,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(2)], OpRef::NONE.raw()),
        ];

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(100, compute as *const () as i64);
        backend.set_constants(constants);

        let token = JitCellToken::new(42);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        // A non-zero args[0] is the already-computed value, so `compute` is
        // not called and the result is args[0] itself, not `5 * 10`. The
        // counter is what separates "skipped" from "called and discarded";
        // the returned value alone cannot.
        let frame = backend.execute_token(&token, &[Value::Int(1), Value::Int(5)]);
        assert_eq!(backend.get_int_value(&frame, 0), 1);
        assert_eq!(unsafe { COND_CALL_VALUE_CALLS }, 0);
    }

    #[test]
    fn test_cond_call_value_i_zero() {
        extern "C" fn compute2(a: i64) -> i64 {
            a * 10
        }

        let mut backend = CraneliftBackend::new();
        let descr = make_call_descr(vec![Type::Int], Type::Int);

        let inputargs = vec![InputArg::new_int_rc(0), InputArg::new_int_rc(1)];
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_int(0), OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
            ),
            mk_op_with_descr(
                OpCode::CondCallValueI,
                &[
                    OpRef::input_arg_int(0),
                    OpRef::int_op(100),
                    OpRef::input_arg_int(1),
                ],
                2,
                descr,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(2)], OpRef::NONE.raw()),
        ];

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(100, compute2 as *const () as i64);
        backend.set_constants(constants);

        let token = JitCellToken::new(43);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        // A zero args[0] is the unfilled cache, so `compute2(5)` runs and its
        // result — not the zero — is what the op produces.
        let frame = backend.execute_token(&token, &[Value::Int(0), Value::Int(5)]);
        assert_eq!(backend.get_int_value(&frame, 0), 50);
    }

    #[test]
    fn test_cond_call_value_r_takes_both_arms() {
        // The Ref twin shares the arm but returns a GC ref, so the fast path
        // hands `cont_block` a live reference rather than a scalar.
        static mut FILL_CACHE_CALLS: i64 = 0;

        extern "C" fn fill_cache(_a: i64) -> i64 {
            unsafe {
                FILL_CACHE_CALLS += 1;
            }
            0x5678
        }

        for (value, expected, expected_calls) in [(0x1234i64, 0x1234i64, 0i64), (0, 0x5678, 1)] {
            unsafe {
                FILL_CACHE_CALLS = 0;
            }

            let mut backend = CraneliftBackend::new();
            let descr = make_call_descr(vec![Type::Ref], Type::Ref);

            let inputargs = vec![InputArg::new_ref_rc(0), InputArg::new_ref_rc(1)];
            let ops = vec![
                mk_op(
                    OpCode::Label,
                    &[OpRef::input_arg_ref(0), OpRef::input_arg_ref(1)],
                    OpRef::NONE.raw(),
                ),
                mk_op_with_descr(
                    OpCode::CondCallValueR,
                    &[
                        OpRef::input_arg_ref(0),
                        OpRef::int_op(100),
                        OpRef::input_arg_ref(1),
                    ],
                    2,
                    descr,
                ),
                mk_op(OpCode::Finish, &[OpRef::ref_op(2)], OpRef::NONE.raw()),
            ];

            let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
            constants.insert(100, fill_cache as *const () as i64);
            backend.set_constants(constants);

            let token = JitCellToken::new(70012);
            backend.compile_loop(&inputargs, &ops, &token).unwrap();

            let frame = backend.execute_token(
                &token,
                &[Value::Ref(GcRef(value as usize)), Value::Ref(GcRef(9))],
            );
            assert_eq!(backend.get_ref_value(&frame, 0), GcRef(expected as usize));
            assert_eq!(unsafe { FILL_CACHE_CALLS }, expected_calls);
        }
    }

    // ── Guard variant tests ──

    #[test]
    fn test_guard_nonnull() {
        let mut backend = CraneliftBackend::new();

        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op(OpCode::Label, &[OpRef::input_arg_int(0)], OpRef::NONE.raw()),
            mk_op(
                OpCode::IntSub,
                &[OpRef::input_arg_int(0), OpRef::int_op(100)],
                1,
            ),
            mk_op(OpCode::GuardNonnull, &[OpRef::int_op(1)], OpRef::NONE.raw()),
            mk_op(OpCode::Jump, &[OpRef::int_op(1)], OpRef::NONE.raw()),
        ];
        ops[2].setfailargs(smallvec::smallvec![rb(OpRef::input_arg_int(0))]);

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(100, 1i64);
        backend.set_constants(constants);

        let token = JitCellToken::new(44);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        // i0=5->i1=4, i0=4->i1=3, ..., i0=1->i1=0 (guard fails).
        // Guard saves the loop inputarg (i0), so saved value is 1.
        let frame = backend.execute_token(&token, &[Value::Int(5)]);
        assert_eq!(backend.get_int_value(&frame, 0), 1);
    }

    #[test]
    fn test_guard_isnull() {
        let cases = [("passes", 45u64, 0i64), ("fails", 46u64, 42i64)];
        for (name, token_id, input) in cases {
            let mut backend = CraneliftBackend::new();

            let inputargs = vec![InputArg::new_int_rc(0)];
            let ops = vec![
                mk_op(OpCode::Label, &[OpRef::input_arg_int(0)], OpRef::NONE.raw()),
                mk_op(
                    OpCode::GuardIsnull,
                    &[OpRef::input_arg_int(0)],
                    OpRef::NONE.raw(),
                ),
                mk_op(
                    OpCode::Finish,
                    &[OpRef::input_arg_int(0)],
                    OpRef::NONE.raw(),
                ),
            ];

            let token = JitCellToken::new(token_id as i64);
            backend.compile_loop(&inputargs, &ops, &token).unwrap();

            let frame = backend.execute_token(&token, &[Value::Int(input)]);
            assert_eq!(backend.get_int_value(&frame, 0), input, "case {name}");
        }
    }

    #[test]
    fn test_guard_value() {
        let mut backend = CraneliftBackend::new();

        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op(OpCode::Label, &[OpRef::input_arg_int(0)], OpRef::NONE.raw()),
            mk_op(
                OpCode::GuardValue,
                &[OpRef::input_arg_int(0), OpRef::int_op(100)],
                OpRef::NONE.raw(),
            ),
            mk_op(
                OpCode::Finish,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
            ),
        ];

        // Test: value matches -> guard passes, reaches Finish
        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(100, 42i64);
        backend.set_constants(constants);

        let token = JitCellToken::new(47);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let frame = backend.execute_token(&token, &[Value::Int(42)]);
        let descr = backend.get_latest_descr(&frame);
        assert!(descr.is_finish()); // Finish
        assert_eq!(backend.get_int_value(&frame, 0), 42);

        // Test: value doesn't match -> guard fails
        let mut constants2: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants2.insert(100, 42i64);
        backend.set_constants(constants2);

        let token2 = JitCellToken::new(48);
        backend.compile_loop(&inputargs, &ops, &token2).unwrap();
        let frame2 = backend.execute_token(&token2, &[Value::Int(99)]);
        let descr2 = backend.get_latest_descr(&frame2);
        assert_eq!(descr2.fail_index(), 0); // guard failure
        assert_eq!(backend.get_int_value(&frame2, 0), 99);
    }

    // ── Test descriptors for field/array ops ──

    use majit_ir::descr::{ArrayDescr, FieldDescr, InteriorFieldDescr};

    #[derive(Debug)]
    struct TestSizeDescr {
        size: usize,
        type_id: u32,
        vtable: usize,
    }

    impl Descr for TestSizeDescr {
        fn as_size_descr(&self) -> Option<&dyn SizeDescr> {
            Some(self)
        }
    }

    impl SizeDescr for TestSizeDescr {
        fn size(&self) -> usize {
            self.size
        }

        fn type_id(&self) -> u32 {
            self.type_id
        }

        fn is_immutable(&self) -> bool {
            false
        }

        fn is_object(&self) -> bool {
            self.vtable != 0
        }

        fn vtable(&self) -> usize {
            self.vtable
        }
    }

    #[derive(Debug)]
    struct TestFieldDescr {
        offset: usize,
        field_size: usize,
        field_type: Type,
        signed: bool,
    }

    impl Descr for TestFieldDescr {
        fn as_field_descr(&self) -> Option<&dyn FieldDescr> {
            Some(self)
        }
    }

    impl FieldDescr for TestFieldDescr {
        fn offset(&self) -> usize {
            self.offset
        }
        fn field_size(&self) -> usize {
            self.field_size
        }
        fn field_type(&self) -> Type {
            self.field_type
        }
        fn is_field_signed(&self) -> bool {
            self.signed
        }
    }

    #[derive(Debug)]
    struct TestArrayDescr {
        base_size: usize,
        item_size: usize,
        item_type: Type,
        signed: bool,
        len_descr: Option<Arc<TestFieldDescr>>,
    }

    #[derive(Debug)]
    struct TestInteriorFieldDescr {
        array_descr: Arc<TestArrayDescr>,
        field_descr: Arc<TestFieldDescr>,
    }

    impl Descr for TestArrayDescr {
        fn as_array_descr(&self) -> Option<&dyn ArrayDescr> {
            Some(self)
        }
    }

    impl ArrayDescr for TestArrayDescr {
        fn base_size(&self) -> usize {
            self.base_size
        }
        fn item_size(&self) -> usize {
            self.item_size
        }
        fn type_id(&self) -> u32 {
            0
        }
        fn item_type(&self) -> Type {
            self.item_type
        }
        fn is_item_signed(&self) -> bool {
            self.signed
        }
        fn len_descr(&self) -> Option<&dyn FieldDescr> {
            self.len_descr
                .as_ref()
                .map(|d| d.as_ref() as &dyn FieldDescr)
        }
    }

    impl Descr for TestInteriorFieldDescr {
        fn as_interior_field_descr(&self) -> Option<&dyn InteriorFieldDescr> {
            Some(self)
        }
    }

    impl InteriorFieldDescr for TestInteriorFieldDescr {
        fn array_descr(&self) -> &dyn ArrayDescr {
            self.array_descr.as_ref()
        }

        fn field_descr(&self) -> &dyn FieldDescr {
            self.field_descr.as_ref()
        }
    }

    fn make_field_descr(
        offset: usize,
        field_size: usize,
        field_type: Type,
        signed: bool,
    ) -> majit_ir::DescrRef {
        Arc::new(TestFieldDescr {
            offset,
            field_size,
            field_type,
            signed,
        })
    }

    fn make_size_descr(size: usize, type_id: u32) -> majit_ir::DescrRef {
        Arc::new(TestSizeDescr {
            size,
            type_id,
            vtable: 0,
        })
    }

    fn make_array_descr(
        base_size: usize,
        item_size: usize,
        item_type: Type,
        len_offset: Option<usize>,
    ) -> majit_ir::DescrRef {
        // descr.py `is_item_signed = flag == FLAG_SIGNED`, over flags
        // that are one value and not a set (descr.py), so only an
        // integer array answers yes. `SimpleArrayDescr::new` derives it the
        // same way; a signed float array is a descr the rewriter's
        // itemsize-negating sign encoding cannot express.
        let signed = item_type == Type::Int;
        make_array_descr_with_signedness(base_size, item_size, item_type, signed, len_offset)
    }

    fn make_array_descr_with_signedness(
        base_size: usize,
        item_size: usize,
        item_type: Type,
        signed: bool,
        len_offset: Option<usize>,
    ) -> majit_ir::DescrRef {
        let len_descr = len_offset.map(|off| {
            Arc::new(TestFieldDescr {
                offset: off,
                field_size: 8,
                field_type: Type::Int,
                signed: true,
            })
        });
        Arc::new(TestArrayDescr {
            base_size,
            item_size,
            item_type,
            signed,
            len_descr,
        })
    }

    fn make_interior_field_descr(
        array_base_size: usize,
        array_item_size: usize,
        array_item_type: Type,
        field_offset: usize,
        field_size: usize,
        field_type: Type,
        field_signed: bool,
    ) -> majit_ir::DescrRef {
        let array_descr = Arc::new(TestArrayDescr {
            base_size: array_base_size,
            item_size: array_item_size,
            item_type: array_item_type,
            signed: true,
            len_descr: None,
        });
        let field_descr = Arc::new(TestFieldDescr {
            offset: field_offset,
            field_size,
            field_type,
            signed: field_signed,
        });
        Arc::new(TestInteriorFieldDescr {
            array_descr,
            field_descr,
        })
    }

    // ── Float comparison tests ──

    #[test]
    fn test_float_comparisons() {
        let mut backend = CraneliftBackend::new();

        let inputargs = vec![InputArg::new_float_rc(0), InputArg::new_float_rc(1)];
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                OpRef::NONE.raw(),
            ),
            mk_op(
                OpCode::FloatLt,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                2,
            ),
            mk_op(
                OpCode::FloatLe,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                3,
            ),
            mk_op(
                OpCode::FloatEq,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                4,
            ),
            mk_op(
                OpCode::FloatNe,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                5,
            ),
            mk_op(
                OpCode::FloatGt,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                6,
            ),
            mk_op(
                OpCode::FloatGe,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                7,
            ),
            mk_op(
                OpCode::Finish,
                &[
                    OpRef::int_op(2),
                    OpRef::int_op(3),
                    OpRef::int_op(4),
                    OpRef::int_op(5),
                    OpRef::int_op(6),
                    OpRef::int_op(7),
                ],
                OpRef::NONE.raw(),
            ),
        ];

        let token = JitCellToken::new(60);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        // 1.5 < 2.5
        let frame = backend.execute_token(&token, &[Value::Float(1.5), Value::Float(2.5)]);
        assert_eq!(backend.get_int_value(&frame, 0), 1); // lt
        assert_eq!(backend.get_int_value(&frame, 1), 1); // le
        assert_eq!(backend.get_int_value(&frame, 2), 0); // eq
        assert_eq!(backend.get_int_value(&frame, 3), 1); // ne
        assert_eq!(backend.get_int_value(&frame, 4), 0); // gt
        assert_eq!(backend.get_int_value(&frame, 5), 0); // ge
    }

    #[test]
    fn test_float_comparisons_equal() {
        let mut backend = CraneliftBackend::new();

        let inputargs = vec![InputArg::new_float_rc(0), InputArg::new_float_rc(1)];
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                OpRef::NONE.raw(),
            ),
            mk_op(
                OpCode::FloatEq,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                2,
            ),
            mk_op(
                OpCode::FloatNe,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                3,
            ),
            mk_op(
                OpCode::FloatLe,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                4,
            ),
            mk_op(
                OpCode::FloatGe,
                &[OpRef::input_arg_float(0), OpRef::input_arg_float(1)],
                5,
            ),
            mk_op(
                OpCode::Finish,
                &[
                    OpRef::int_op(2),
                    OpRef::int_op(3),
                    OpRef::int_op(4),
                    OpRef::int_op(5),
                ],
                OpRef::NONE.raw(),
            ),
        ];

        let token = JitCellToken::new(61);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let frame = backend.execute_token(&token, &[Value::Float(3.25), Value::Float(3.25)]);
        assert_eq!(backend.get_int_value(&frame, 0), 1); // eq
        assert_eq!(backend.get_int_value(&frame, 1), 0); // ne
        assert_eq!(backend.get_int_value(&frame, 2), 1); // le
        assert_eq!(backend.get_int_value(&frame, 3), 1); // ge
    }

