    #[test]
    fn test_raw_store_and_load_f_roundtrip() {
        let mut backend = CraneliftBackend::new();

        let ad = make_array_descr(0, 8, Type::Float, None);
        let inputargs = vec![InputArg::new_ref_rc(0), InputArg::new_float_rc(1)];
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_ref(0), OpRef::input_arg_float(1)],
                OpRef::NONE.raw(),
            ),
            mk_op_with_descr(
                OpCode::RawStore,
                &[
                    OpRef::input_arg_ref(0),
                    OpRef::int_op(100),
                    OpRef::input_arg_float(1),
                ],
                OpRef::NONE.raw(),
                ad.clone(),
            ),
            mk_op_with_descr(
                OpCode::RawLoadF,
                &[OpRef::input_arg_ref(0), OpRef::int_op(100)],
                2,
                ad,
            ),
            mk_op(OpCode::Finish, &[OpRef::float_op(2)], OpRef::NONE.raw()),
        ];

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(100, 2);
        backend.set_constants(constants);

        let token = JitCellToken::new(99);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        // 8-byte f64 write at offset 2 needs at least 10 bytes; round up so
        // the buffer also satisfies stricter heap-block layouts on Windows.
        let mut data = vec![0u8; 16];
        let ptr = data.as_mut_ptr() as usize;

        let frame = backend.execute_token(&token, &[Value::Ref(GcRef(ptr)), Value::Float(6.25)]);
        assert!((backend.get_float_value(&frame, 0) - 6.25).abs() < 1e-10);
    }

    /// rewrite.py:319-330 reads `GC_LOAD_INDEXED`'s scale, offset and size
    /// under `assert isinstance(..., ConstInt)`, and x86/regalloc.py:1178-1182
    /// asserts the same three again in the backend: a variable scale violates
    /// the opcode's contract rather than asking the backend for a capability
    /// it lacks. The rewriter states it the same way and runs ahead of the
    /// backend, so that is where the trace stops.
    #[test]
    #[should_panic(expected = "GC_LOAD_INDEXED scale must be ConstInt")]
    fn test_gc_load_indexed_rejects_nonconstant_scale() {
        let mut backend = CraneliftBackend::new();

        let inputargs = vec![
            InputArg::new_ref_rc(0),
            InputArg::new_int_rc(1),
            InputArg::new_int_rc(2),
        ];
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[
                    OpRef::input_arg_ref(0),
                    OpRef::input_arg_int(1),
                    OpRef::input_arg_int(2),
                ],
                OpRef::NONE.raw(),
            ),
            mk_op(
                OpCode::GcLoadIndexedI,
                &[
                    OpRef::input_arg_ref(0),
                    OpRef::input_arg_int(1),
                    OpRef::input_arg_int(2),
                    OpRef::int_op(100),
                    OpRef::int_op(101),
                ],
                3,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(3)], OpRef::NONE.raw()),
        ];

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(100, 2);
        constants.insert(101, 8);
        backend.set_constants(constants);

        let token = JitCellToken::new(100);
        let _ = backend.compile_loop(&inputargs, &ops, &token);
    }

