    #[test]
    fn test_call_may_force_n_guard_not_forced_and_savedata() {
        let _guard = may_force_test_lock().lock();
        may_force_void_values().lock().clear();

        let mut backend = CraneliftBackend::new();
        let descr = make_call_descr(vec![Type::Ref, Type::Int], Type::Void);
        let inputargs = vec![InputArg::new_int_rc(0), InputArg::new_int_rc(1)];
        let guard_op = mk_op(OpCode::GuardNotForced, &[], OpRef::NONE.raw());
        guard_op.setfailargs(smallvec::smallvec![
            rb(OpRef::input_arg_int(1)),
            rb(OpRef::input_arg_int(0)),
        ]);
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_int(0), OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
            ),
            mk_op(OpCode::ForceToken, &[], 2),
            mk_op_with_descr(
                OpCode::CallMayForceN,
                &[
                    OpRef::int_op(100),
                    OpRef::ref_op(2),
                    OpRef::input_arg_int(1),
                ],
                OpRef::NONE.raw(),
                descr,
            ),
            guard_op,
            mk_op(
                OpCode::Finish,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
            ),
        ];

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(
            100,
            maybe_force_and_return_void as *const () as usize as i64,
        );
        backend.set_constants(constants);

        let token = JitCellToken::new(1_500_400);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let frame = backend.execute_token(&token, &[Value::Int(20), Value::Int(0)]);
        assert!(backend.get_latest_descr(&frame).is_finish());
        assert_eq!(backend.get_int_value(&frame, 0), 20);
        assert!(may_force_void_values().lock().is_empty());

        let frame = backend.execute_token(&token, &[Value::Int(10), Value::Int(1)]);
        assert_eq!(backend.get_latest_descr(&frame).fail_index(), 0);
        assert_eq!(backend.get_int_value(&frame, 0), 1);
        assert_eq!(backend.get_int_value(&frame, 1), 10);
        assert_eq!(*may_force_void_values().lock(), vec![0, 1, 10]);
        assert_eq!(backend.get_savedata_ref(&frame).unwrap(), GcRef(0xDADA));
    }

    #[test]
    fn test_guard_not_forced_2_preserves_overlapping_failarg_sources() {
        let mut backend = CraneliftBackend::new();
        let inputargs = vec![InputArg::new_int_rc(0), InputArg::new_int_rc(1)];
        let guard = mk_op(OpCode::GuardNotForced2, &[], OpRef::NONE.raw());
        guard.setfailargs(smallvec::smallvec![
            rb(OpRef::input_arg_int(1)),
            rb(OpRef::input_arg_int(0)),
        ]);
        guard.set_fail_arg_types(vec![Type::Int, Type::Int]);
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_int(0), OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
            ),
            mk_op(OpCode::ForceToken, &[], 2),
            guard,
            mk_op(OpCode::Finish, &[OpRef::ref_op(2)], OpRef::NONE.raw()),
        ];

        let token = JitCellToken::new(1_500_401);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();
        let returned = backend.execute_token(&token, &[Value::Int(11), Value::Int(22)]);
        let force_token = backend.get_ref_value(&returned, 0);
        let forced = backend.force(force_token).expect("armed force token");
        assert_eq!(backend.get_int_value(&forced, 0), 22);
        assert_eq!(backend.get_int_value(&forced, 1), 11);
    }

    #[test]
    fn test_execute_token_ints_raw_preserves_savedata_and_layout_for_call_may_force() {
        let _guard = may_force_test_lock().lock();
        may_force_void_values().lock().clear();

        let mut backend = CraneliftBackend::new();
        let descr = make_call_descr(vec![Type::Ref, Type::Int], Type::Void);
        let inputargs = vec![InputArg::new_int_rc(0), InputArg::new_int_rc(1)];
        let guard_op = mk_op(OpCode::GuardNotForced, &[], OpRef::NONE.raw());
        guard_op.setfailargs(smallvec::smallvec![
            rb(OpRef::input_arg_int(1)),
            rb(OpRef::input_arg_int(0)),
        ]);
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_int(0), OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
            ),
            mk_op(OpCode::ForceToken, &[], 2),
            mk_op_with_descr(
                OpCode::CallMayForceN,
                &[
                    OpRef::int_op(100),
                    OpRef::ref_op(2),
                    OpRef::input_arg_int(1),
                ],
                OpRef::NONE.raw(),
                descr,
            ),
            guard_op,
            mk_op(
                OpCode::Finish,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
            ),
        ];

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(
            100,
            maybe_force_and_return_void as *const () as usize as i64,
        );
        backend.set_constants(constants);

        let token = JitCellToken::new(1_500_404);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let raw = backend.execute_token_ints_raw(&token, &[10, 1]);
        assert!(!raw.is_finish);
        assert_eq!(raw.fail_index, 0);
        assert_eq!(raw.outputs, vec![1, 10]);
        assert_eq!(raw.typed_outputs, vec![Value::Int(1), Value::Int(10)]);
        assert_eq!(raw.savedata, Some(GcRef(0xDADA)));
        assert_eq!(raw.exception_value, GcRef::NULL);
        let fd = raw
            .descr_arc
            .as_fail_descr()
            .expect("raw exit carries a FailDescr");
        assert_eq!(fd.fail_index(), 0);
        assert_eq!(fd.source_op_index(), Some(3));
        assert_eq!(*may_force_void_values().lock(), vec![0, 1, 10]);
    }

    #[test]
    fn test_call_may_force_with_intervening_ops() {
        let _guard = may_force_test_lock().lock();
        // RPython parity: `_genop_call_may_force` takes the paired guard
        // via `_find_nearby_operation(+1)` (x86/assembler.py)
        // — the optimizer is required to keep CALL_MAY_FORCE and
        // GUARD_NOT_FORCED adjacent. The cranelift backend mirrors the
        // assertion; any intervening op (here, a SameAsI between the call
        // and its guard) must be rejected at compile time.
        let descr = make_call_descr(vec![Type::Ref, Type::Int], Type::Int);
        let inputargs = vec![InputArg::new_int_rc(0), InputArg::new_int_rc(1)];
        let guard_op = mk_op(OpCode::GuardNotForced, &[], OpRef::NONE.raw());
        guard_op.setfailargs(smallvec::smallvec![
            rb(OpRef::input_arg_int(1)),
            rb(OpRef::int_op(3)),
            rb(OpRef::input_arg_int(0)),
        ]);
        let ops = vec![
            mk_op(
                OpCode::Label,
                &[OpRef::input_arg_int(0), OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
            ),
            mk_op(OpCode::ForceToken, &[], 2),
            mk_op_with_descr(
                OpCode::CallMayForceI,
                &[
                    OpRef::int_op(100),
                    OpRef::ref_op(2),
                    OpRef::input_arg_int(1),
                ],
                3,
                descr,
            ),
            mk_op(OpCode::SameAsI, &[OpRef::int_op(3)], 4),
            guard_op,
            mk_op(OpCode::Finish, &[OpRef::int_op(4)], OpRef::NONE.raw()),
        ];

        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(
            100,
            maybe_force_and_return_int_isolated as *const () as usize as i64,
        );
        let mut backend = CraneliftBackend::new();
        backend.set_constants(constants);
        let token = JitCellToken::new(1_500_410);
        let err = backend.compile_loop(&inputargs, &ops, &token).unwrap_err();
        let msg = format!("{err:?}");
        assert!(
            msg.contains("expected guard_not_forced(_2) at +1") && msg.contains("SameAsI"),
            "unexpected error message: {msg}"
        );
    }

