    #[test]
    #[ignore = "sets the process-global MAJIT_CL_NO_CLOSING_JUMP env var to force the \
        host-loop external-JUMP path (in-code closing_jump disabled); run serially: \
        `MAJIT_CL_NO_CLOSING_JUMP=1 cargo test -p majit-backend-cranelift \
        test_host_loop_external_jump_to_middle_label -- --ignored --test-threads=1`"]
    fn test_host_loop_external_jump_to_middle_label_uses_label_selector() {
        // Same scenario as the in-code variant above, but with closing_jump
        // disabled the cross-loop JUMP surfaces as an `is_external_jump`
        // deadframe and the host loop (`execute_with_inputs`) re-enters the
        // target via its wrapper.  `host_reentry_dispatch_key` must pass the
        // middle LABEL's `label_block_id + 1` so the body's entry `br_table`
        // selects the loader (reading the carried value run_compiled_code
        // loaded into slot 0) instead of the preamble — which would re-run
        // the start LABEL and finish 35 instead of 25.
        unsafe { std::env::set_var("MAJIT_CL_NO_CLOSING_JUMP", "1") };

        let mut backend = CraneliftBackend::new();
        let start_descr = make_label_descr(1_500_280);
        let middle_descr = make_label_descr(1_500_281);
        let final_descr = make_label_descr(1_500_282);

        let inputargs = vec![InputArg::new_int_rc(0)];
        let guard = mk_op(OpCode::GuardTrue, &[OpRef::int_op(1)], OpRef::NONE.raw());
        guard.setfailargs(smallvec::smallvec![rb(OpRef::input_arg_int(0))]);
        let root_ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_int(0)],
                OpRef::NONE.raw(),
                start_descr,
            ),
            mk_op(
                OpCode::IntGt,
                &[OpRef::input_arg_int(0), OpRef::int_op(100)],
                1,
            ),
            guard,
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::int_op(101)],
                2,
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(2)],
                OpRef::NONE.raw(),
                middle_descr.clone(),
            ),
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::int_op(3)],
                OpRef::NONE.raw(),
                middle_descr.clone(),
            ),
            mk_op(OpCode::IntAdd, &[OpRef::int_op(3), OpRef::int_op(102)], 4),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(4)],
                OpRef::NONE.raw(),
                final_descr.clone(),
            ),
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::int_op(5)],
                OpRef::NONE.raw(),
                final_descr,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(5)], OpRef::NONE.raw()),
        ];

        let mut root_constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        root_constants.insert(100, 0);
        root_constants.insert(101, 10);
        root_constants.insert(102, 20);
        backend.set_constants(root_constants);

        let token = JitCellToken::new(1_500_283);
        backend.compile_loop(&inputargs, &root_ops, &token).unwrap();

        let failed = backend.execute_token(&token, &[Value::Int(0)]);
        let guard_descr =
            get_latest_descr_from_deadframe(&failed).expect("guard should produce a descr");

        let mut bridge_constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        bridge_constants.insert(103, 5);
        backend.set_constants(bridge_constants);
        let bridge_ops = vec![
            mk_op(OpCode::Label, &[OpRef::input_arg_int(0)], OpRef::NONE.raw()),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::int_op(103)],
                1,
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                middle_descr,
            ),
        ];
        backend
            .compile_bridge(guard_descr, &inputargs, &bridge_ops, &token)
            .unwrap();

        backend.set_constants(indexmap::IndexMap::new());
        let frame = backend.execute_token(&token, &[Value::Int(0)]);
        let is_finish = backend.get_latest_descr(&frame).is_finish();
        let value = backend.get_int_value(&frame, 0);

        unsafe { std::env::remove_var("MAJIT_CL_NO_CLOSING_JUMP") };

        assert!(is_finish);
        assert_eq!(value, 25);
    }

    #[test]
    #[ignore = "sets the process-global MAJIT_CL_NO_CLOSING_JUMP env var to force the \
        host-loop external-JUMP path (in-code closing_jump disabled); run serially: \
        `MAJIT_CL_NO_CLOSING_JUMP=1 cargo test -p majit-backend-cranelift \
        test_host_loop_external_jump_to_first_label -- --ignored --test-threads=1`"]
    fn test_host_loop_external_jump_to_first_label_uses_label_selector() {
        // The first LABEL (`label_block_id` 0) is not special: `closing_jump`
        // (assembler.py:2456-2462) branches to `target._ll_loop_code` for it
        // too, never the preamble.  Here a peeled preamble (`IntAdd +1000`)
        // precedes the start LABEL, then a bridge JUMPs back to the start
        // descr.  With closing_jump disabled the JUMP surfaces as an
        // `is_external_jump` deadframe and the host loop re-enters via the
        // wrapper.  `host_reentry_dispatch_key` must pass `0 + 1` (the start
        // LABEL's loader) so the carried value (5) reaches the body verbatim
        // and it finishes 15.  Routing the first LABEL to the preamble (key 0)
        // would re-run the `+1000` and finish 1015 instead.
        unsafe { std::env::set_var("MAJIT_CL_NO_CLOSING_JUMP", "1") };

        let mut backend = CraneliftBackend::new();
        let start_descr = make_label_descr(1_500_290);
        let final_descr = make_label_descr(1_500_291);

        let inputargs = vec![InputArg::new_int_rc(0)];
        let guard = mk_op(OpCode::GuardTrue, &[OpRef::int_op(2)], OpRef::NONE.raw());
        guard.setfailargs(smallvec::smallvec![rb(OpRef::int_op(1))]);
        let root_ops = vec![
            // Peeled preamble: runs once on the initial host entry, before the
            // first LABEL.  A loader re-entry must skip it.
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::int_op(200)],
                1,
            ),
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                start_descr.clone(),
            ),
            mk_op(OpCode::IntGt, &[OpRef::int_op(1), OpRef::int_op(100)], 2),
            guard,
            mk_op(OpCode::IntAdd, &[OpRef::int_op(1), OpRef::int_op(101)], 3),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(3)],
                OpRef::NONE.raw(),
                final_descr.clone(),
            ),
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::int_op(4)],
                OpRef::NONE.raw(),
                final_descr,
            ),
            mk_op(OpCode::Finish, &[OpRef::int_op(4)], OpRef::NONE.raw()),
        ];

        let mut root_constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        root_constants.insert(200, 1000);
        root_constants.insert(100, 0);
        root_constants.insert(101, 10);
        backend.set_constants(root_constants);

        let token = JitCellToken::new(1_500_292);
        backend.compile_loop(&inputargs, &root_ops, &token).unwrap();

        let failed = backend.execute_token(&token, &[Value::Int(-1000)]);
        let guard_descr =
            get_latest_descr_from_deadframe(&failed).expect("guard should produce a descr");

        let mut bridge_constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        bridge_constants.insert(103, 5);
        backend.set_constants(bridge_constants);
        let bridge_ops = vec![
            mk_op(OpCode::Label, &[OpRef::input_arg_int(0)], OpRef::NONE.raw()),
            mk_op(
                OpCode::IntAdd,
                &[OpRef::input_arg_int(0), OpRef::int_op(103)],
                1,
            ),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::int_op(1)],
                OpRef::NONE.raw(),
                start_descr,
            ),
        ];
        backend
            .compile_bridge(guard_descr, &inputargs, &bridge_ops, &token)
            .unwrap();

        backend.set_constants(indexmap::IndexMap::new());
        let frame = backend.execute_token(&token, &[Value::Int(-1000)]);
        let is_finish = backend.get_latest_descr(&frame).is_finish();
        let value = backend.get_int_value(&frame, 0);

        unsafe { std::env::remove_var("MAJIT_CL_NO_CLOSING_JUMP") };

        assert!(is_finish);
        assert_eq!(value, 15);
    }

    #[test]
    #[ignore = "sets the process-global MAJIT_CL_NO_CLOSING_JUMP env var to force the \
        host-loop external-JUMP path (in-code closing_jump disabled); run serially: \
        `MAJIT_CL_NO_CLOSING_JUMP=1 cargo test -p majit-backend-cranelift \
        test_raw_done_ref_external_jump_matches_general -- --ignored --test-threads=1`"]
    fn test_raw_done_ref_external_jump_matches_general() {
        unsafe { std::env::set_var("MAJIT_CL_NO_CLOSING_JUMP", "1") };

        let mut backend = CraneliftBackend::new();
        let target_descr = make_label_descr(1_500_410);
        let target_inputargs = vec![InputArg::new_ref_rc(0)];
        let target_ops = vec![
            mk_op_with_descr(
                OpCode::Label,
                &[OpRef::input_arg_ref(0)],
                OpRef::NONE.raw(),
                target_descr.clone(),
            ),
            mk_op(
                OpCode::Finish,
                &[OpRef::input_arg_ref(0)],
                OpRef::NONE.raw(),
            ),
        ];
        let target_token = JitCellToken::new(1_500_411);
        backend
            .compile_loop(&target_inputargs, &target_ops, &target_token)
            .unwrap();

        let source_inputargs = vec![InputArg::new_ref_rc(0)];
        let source_ops = vec![
            mk_op(OpCode::Label, &[OpRef::input_arg_ref(0)], OpRef::NONE.raw()),
            mk_op_with_descr(
                OpCode::Jump,
                &[OpRef::input_arg_ref(0)],
                OpRef::NONE.raw(),
                target_descr,
            ),
        ];
        let source_token = JitCellToken::new(1_500_412);
        backend
            .compile_loop(&source_inputargs, &source_ops, &source_token)
            .unwrap();

        let referent = 0xCAFEusize;
        let ptr = &referent as *const usize as i64;
        let general = match backend
            .execute_token_done_ref(&source_token, &[Value::Ref(GcRef(ptr as usize))])
        {
            Ok(value) => value,
            Err(_) => panic!("general done-ref after JUMP"),
        };
        let raw = match backend.execute_token_done_ref_raw(&source_token, &[ptr]) {
            Ok(value) => value,
            Err(_) => panic!("raw done-ref after JUMP"),
        };

        unsafe { std::env::remove_var("MAJIT_CL_NO_CLOSING_JUMP") };

        assert_eq!(raw, general);
        assert_eq!(general, ptr as usize);
    }

