    #[test]
    fn test_gc_runtime_opcodes_error() {
        let cases = vec![
            (
                OpCode::CallMallocNursery,
                vec![InputArg::new_int_rc(0)],
                vec![OpRef::input_arg_ref(0)],
                1,
                "configured GC runtime",
            ),
            (
                OpCode::CallMallocNurseryVarsize,
                vec![
                    InputArg::new_int_rc(0),
                    InputArg::new_int_rc(1),
                    InputArg::new_int_rc(2),
                ],
                vec![
                    OpRef::input_arg_ref(0),
                    OpRef::input_arg_int(1),
                    OpRef::input_arg_int(2),
                ],
                3,
                "configured GC runtime",
            ),
            (
                OpCode::CallMallocNurseryVarsizeFrame,
                vec![InputArg::new_int_rc(0)],
                vec![OpRef::input_arg_ref(0)],
                1,
                "configured GC runtime",
            ),
            (
                OpCode::CondCallGcWb,
                vec![InputArg::new_ref_rc(0)],
                vec![OpRef::input_arg_ref(0)],
                OpRef::NONE.raw(),
                "configured GC runtime",
            ),
            (
                OpCode::CondCallGcWbArray,
                vec![InputArg::new_ref_rc(0), InputArg::new_int_rc(1)],
                vec![OpRef::input_arg_ref(0), OpRef::input_arg_int(1)],
                OpRef::NONE.raw(),
                "configured GC runtime",
            ),
        ];

        for (idx, (opcode, inputargs, op_args, pos, detail)) in cases.into_iter().enumerate() {
            let label_args: Vec<OpRef> = (0..inputargs.len() as u32).map(OpRef::int_op).collect();
            let ops = vec![
                mk_op(OpCode::Label, &label_args, OpRef::NONE.raw()),
                mk_op(opcode, &op_args, pos),
                mk_op(
                    OpCode::Finish,
                    &[OpRef::input_arg_ref(0)],
                    OpRef::NONE.raw(),
                ),
            ];
            assert_compile_unsupported(inputargs, ops, 1400 + idx as u64, opcode, detail);
        }
    }

    #[test]
    fn test_gc_alloc_and_init_with_configured_runtime() {
        let mut backend = make_gc_backend();
        // Constants: 10000=32(size), 10001=-8(tid_ofs), 10002=7(tid),
        // 10003=8(word), 10004=0(vtable_ofs), 10005=0xDEAD(vtable)
        let mut consts: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        consts.insert(10000, 32_i64);
        consts.insert(10001, -8_i64);
        consts.insert(10002, 7_i64);
        consts.insert(10003, 8_i64);
        consts.insert(10004, 0_i64);
        consts.insert(10005, 0xDEAD_i64);
        backend.set_constants(consts);

        let inputargs = vec![];
        let ops = vec![
            mk_op(OpCode::CallMallocNursery, &[OpRef::int_op(10000)], 0),
            mk_op(
                OpCode::GcStore,
                &[
                    OpRef::ref_op(0),
                    OpRef::int_op(10001),
                    OpRef::int_op(10002),
                    OpRef::int_op(10003),
                ],
                OpRef::NONE.raw(),
            ),
            mk_op(
                OpCode::GcStore,
                &[
                    OpRef::ref_op(0),
                    OpRef::int_op(10004),
                    OpRef::int_op(10005),
                    OpRef::int_op(10003),
                ],
                OpRef::NONE.raw(),
            ),
            mk_op(OpCode::Finish, &[OpRef::ref_op(0)], OpRef::NONE.raw()),
        ];

        let token = JitCellToken::new(1500);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let frame = backend.execute_token(&token, &[]);
        let obj = backend.get_ref_value(&frame, 0);
        assert!(!obj.is_null());
        assert_eq!(unsafe { (*header_of(obj.0)).type_id() }, 7);
        assert_eq!(unsafe { *(obj.0 as *const u64) }, 0xDEAD);
        let clif = backend.last_body_clif.clone();
        assert!(
            tid_store_address_op(&clif, 7, "load"),
            "fast path must store tid 7 at nursery free:\n{clif}"
        );
        assert!(
            tid_store_address_op(&clif, 7, "iadd"),
            "GcStore of tid 7 must still run:\n{clif}"
        );
    }

    /// `CallMallocNurseryVarsizeFrame` fast path plus
    /// `gen_initialize_tid_keep_flags`. `malloc_cond_varsize_frame` writes
    /// the whole header word first so a recycled slot's `HAS_SHADOW` is
    /// cleared before the 4-byte type-id store.
    #[test]
    fn varsize_frame_fast_path_clears_recycled_has_shadow() {
        let mut backend = make_gc_backend();
        let mut consts: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        consts.insert(10000, 32_i64);
        consts.insert(10001, -8_i64);
        consts.insert(10002, 7_i64);
        consts.insert(10003, (TYPE_ID_BITS / 8) as i64);
        backend.set_constants(consts);

        let inputargs = vec![];
        let ops = vec![
            mk_op(
                OpCode::CallMallocNurseryVarsizeFrame,
                &[OpRef::int_op(10000)],
                0,
            ),
            mk_op(
                OpCode::GcStore,
                &[
                    OpRef::ref_op(0),
                    OpRef::int_op(10001),
                    OpRef::int_op(10002),
                    OpRef::int_op(10003),
                ],
                OpRef::NONE.raw(),
            ),
            mk_op(OpCode::Finish, &[OpRef::ref_op(0)], OpRef::NONE.raw()),
        ];

        let token = JitCellToken::new(1506);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        with_cranelift_gc_required(|gc| {
            let p = gc.nursery_free();
            assert!(!p.is_null());
            let mut dirty = GcHeader::new(99);
            dirty.set_flag(GcFlags::GCFLAG_HAS_SHADOW);
            unsafe {
                std::ptr::write(p as *mut GcHeader, dirty);
            }
        });

        let frame = backend.execute_token(&token, &[]);
        let obj = backend.get_ref_value(&frame, 0);
        assert!(!obj.is_null());
        let hdr = unsafe { *header_of(obj.0) };
        assert_eq!(hdr.type_id(), 7);
        assert!(
            !hdr.has_flag(GcFlags::GCFLAG_HAS_SHADOW),
            "varsize-frame fast path must clear HAS_SHADOW from a recycled slot, hdr={:#x}",
            hdr.tid_and_flags
        );
        let clif = backend.last_body_clif.clone();
        assert!(
            tid_store_address_op(&clif, 0, "load"),
            "fast path must zero the header word at nursery free:\n{clif}"
        );
    }

    #[test]
    fn test_gc_batched_allocation_layout_with_configured_runtime() {
        let mut backend = make_gc_backend();
        // Constants: 10000=56(total_size), 10001=-8(tid_ofs), 10002=1(tid1),
        // 10003=8(word), 10004=24(incr), 10005=2(tid2)
        let mut consts: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        consts.insert(10000, 56_i64);
        consts.insert(10001, -8_i64);
        consts.insert(10002, 1_i64);
        consts.insert(10003, 8_i64);
        consts.insert(10004, 24_i64);
        consts.insert(10005, 2_i64);
        backend.set_constants(consts);

        let inputargs = vec![];
        let ops = vec![
            mk_op(OpCode::CallMallocNursery, &[OpRef::int_op(10000)], 0),
            mk_op(
                OpCode::GcStore,
                &[
                    OpRef::ref_op(0),
                    OpRef::int_op(10001),
                    OpRef::int_op(10002),
                    OpRef::int_op(10003),
                ],
                OpRef::NONE.raw(),
            ),
            mk_op(
                OpCode::NurseryPtrIncrement,
                &[OpRef::ref_op(0), OpRef::int_op(10004)],
                1,
            ),
            mk_op(
                OpCode::GcStore,
                &[
                    OpRef::ref_op(1),
                    OpRef::int_op(10001),
                    OpRef::int_op(10005),
                    OpRef::int_op(10003),
                ],
                OpRef::NONE.raw(),
            ),
            mk_op(
                OpCode::Finish,
                &[OpRef::ref_op(0), OpRef::ref_op(1)],
                OpRef::NONE.raw(),
            ),
        ];

        let token = JitCellToken::new(1501);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let frame = backend.execute_token(&token, &[]);
        let obj0 = backend.get_ref_value(&frame, 0);
        let obj1 = backend.get_ref_value(&frame, 1);

        assert!(!obj0.is_null());
        assert!(!obj1.is_null());
        assert_eq!(obj1.0, obj0.0 + 24);
        assert_eq!(unsafe { (*header_of(obj0.0)).type_id() }, 1);
        assert_eq!(unsafe { (*header_of(obj1.0)).type_id() }, 2);
        let clif = backend.last_body_clif.clone();
        assert!(
            tid_store_address_op(&clif, 1, "load"),
            "fast path must store tid 1 at nursery free:\n{clif}"
        );
        assert!(
            tid_store_address_op(&clif, 1, "iadd"),
            "GcStore of tid 1 must still run:\n{clif}"
        );
        assert!(
            !tid_store_address_op(&clif, 2, "load"),
            "interior tid 2 is not written at nursery free:\n{clif}"
        );
    }

    #[test]
    fn following_nursery_tid_reads_pool_and_inline_consts() {
        let mut constants: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        constants.insert(10001, -8);
        constants.insert(10002, 7);
        constants.insert(10003, 8);
        let malloc = mk_op(OpCode::CallMallocNursery, &[OpRef::int_op(10000)], 0);
        let pooled = mk_op(
            OpCode::GcStore,
            &[
                OpRef::ref_op(0),
                OpRef::int_op(10001),
                OpRef::int_op(10002),
                OpRef::int_op(10003),
            ],
            OpRef::NONE.raw(),
        );
        assert_eq!(
            super::following_nursery_tid(&malloc, &pooled, &constants),
            Some(7)
        );

        let inline = mk_op(
            OpCode::GcStore,
            &[
                OpRef::ref_op(0),
                OpRef::const_int(-(GcHeader::SIZE as i64)),
                OpRef::const_int(9),
                OpRef::const_int(std::mem::size_of::<usize>() as i64),
            ],
            OpRef::NONE.raw(),
        );
        assert_eq!(
            super::following_nursery_tid(&malloc, &inline, &constants),
            Some(9)
        );

        let keep_flags = mk_op(
            OpCode::GcStore,
            &[
                OpRef::ref_op(0),
                OpRef::const_int(-(GcHeader::SIZE as i64)),
                OpRef::const_int(11),
                OpRef::const_int((TYPE_ID_BITS / 8) as i64),
            ],
            OpRef::NONE.raw(),
        );
        assert_eq!(
            super::following_nursery_tid(&malloc, &keep_flags, &constants),
            Some(11)
        );

        let wrong_base = mk_op(
            OpCode::GcStore,
            &[
                OpRef::ref_op(1),
                OpRef::int_op(10001),
                OpRef::int_op(10002),
                OpRef::int_op(10003),
            ],
            OpRef::NONE.raw(),
        );
        assert_eq!(
            super::following_nursery_tid(&malloc, &wrong_base, &constants),
            None
        );
    }

    fn tid_store_address_op(clif: &str, tid: i64, addr_prefix: &str) -> bool {
        let defs = clif_value_defs(clif);
        let want = format!("iconst.i64 {tid}");
        for line in clif.lines() {
            let Some((val, addr)) = clif_store_operands(line) else {
                continue;
            };
            if clif_def_head(&ultimate_clif_def(&defs, &val)) != want {
                continue;
            }
            if clif_def_head(&ultimate_clif_def(&defs, &addr)).starts_with(addr_prefix) {
                return true;
            }
        }
        false
    }

    fn clif_value_defs(clif: &str) -> std::collections::HashMap<String, String> {
        let mut defs = std::collections::HashMap::new();
        for line in clif.lines() {
            let t = line.trim().split("  ;").next().unwrap_or("").trim();
            if let Some((lhs, rhs)) = t.split_once(" = ") {
                if clif_is_value(lhs) {
                    defs.insert(lhs.to_string(), rhs.to_string());
                }
            } else if let Some((lhs, rhs)) = t.split_once(" -> ")
                && clif_is_value(lhs.trim())
            {
                defs.insert(lhs.trim().to_string(), format!("alias {}", rhs.trim()));
            }
        }
        defs
    }

    fn clif_is_value(name: &str) -> bool {
        let mut chars = name.chars();
        chars.next() == Some('v') && chars.all(|c| c.is_ascii_digit())
    }

    fn ultimate_clif_def(defs: &std::collections::HashMap<String, String>, name: &str) -> String {
        let mut cur = name.to_string();
        for _ in 0..32 {
            match defs.get(&cur).map(String::as_str) {
                Some(rhs) => {
                    if let Some(next) = rhs.strip_prefix("alias ") {
                        cur = next.trim().to_string();
                    } else {
                        return rhs.to_string();
                    }
                }
                None => return String::new(),
            }
        }
        String::new()
    }

    fn clif_def_head(def: &str) -> &str {
        def.split("  ;").next().unwrap_or(def).trim()
    }

    fn clif_store_operands(line: &str) -> Option<(String, String)> {
        let t = line.trim().split("  ;").next()?.trim();
        let rest = t.strip_prefix("store")?;
        let (before, addr) = rest.rsplit_once(',')?;
        let val = before.split_whitespace().last()?.trim();
        if !clif_is_value(val) {
            return None;
        }
        let addr = addr.trim();
        if addr.contains('+') || addr.contains('-') || !clif_is_value(addr) {
            return None;
        }
        Some((val.to_string(), addr.to_string()))
    }

    #[test]
    fn test_gc_varsize_alloc_and_length_init_with_configured_runtime() {
        let mut backend = make_gc_backend();
        // Constants: 10000=0(len_ofs), 10001=8(size), 10002=0(kind), 10003=8(itemsize)
        let mut consts: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        consts.insert(10000, 0_i64);
        consts.insert(10001, 8_i64);
        consts.insert(10002, 0_i64); // FLAG_ARRAY
        consts.insert(10003, 8_i64); // itemsize
        backend.set_constants(consts);

        let ad = make_array_descr(16, 8, Type::Int, Some(0));
        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op(OpCode::Label, &[OpRef::input_arg_int(0)], OpRef::NONE.raw()),
            // rewrite.py:858: [ConstInt(kind), ConstInt(itemsize), v_length]
            mk_op_with_descr(
                OpCode::CallMallocNurseryVarsize,
                &[
                    OpRef::int_op(10002),
                    OpRef::int_op(10003),
                    OpRef::input_arg_int(0),
                ],
                1,
                ad.clone(),
            ),
            mk_op(
                OpCode::GcStore,
                &[
                    OpRef::ref_op(1),
                    OpRef::int_op(10000),
                    OpRef::input_arg_int(0),
                    OpRef::int_op(10001),
                ],
                OpRef::NONE.raw(),
            ),
            mk_op(OpCode::Finish, &[OpRef::ref_op(1)], OpRef::NONE.raw()),
        ];

        let token = JitCellToken::new(1502);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let frame = backend.execute_token(&token, &[Value::Int(3)]);
        let obj = backend.get_ref_value(&frame, 0);
        assert!(!obj.is_null());
        assert_eq!(unsafe { *(obj.0 as *const i64) }, 3);

        // `malloc_cond_varsize` sends over-threshold lengths through the
        // collecting helper.  The result is a born-old external allocation.
        let large_length = 140_000;
        let frame = backend.execute_token(&token, &[Value::Int(large_length)]);
        let obj = backend.get_ref_value(&frame, 0);
        assert!(!obj.is_null());
        assert_eq!(unsafe { *(obj.0 as *const i64) }, large_length);
        assert!(!majit_gc::can_move(obj));
    }

    #[test]
    fn test_gc_call_malloc_array_helper_with_configured_runtime() {
        // The production helper receives a layout-registry type id.  Keep the
        // fixture subject to that same contract: a header carrying an
        // unregistered `7` is not a typed array and becomes an out-of-bounds
        // type-table read as soon as a collection traces it.
        let mut gc = MiniMarkGC::with_config(GcConfig {
            nursery_size: 1 << 20,
            large_object_threshold: 1 << 20,
            ..GcConfig::default()
        });
        for _ in 0..7 {
            gc.register_type(TypeInfo::simple(16));
        }
        let array_tid = gc.register_type(TypeInfo::varsize(8, 8, 0, false, Vec::new()));
        assert_eq!(array_tid, 7);
        let mut backend = backend_with_gc(gc);
        let mut consts: indexmap::IndexMap<u32, i64> = indexmap::IndexMap::new();
        consts.insert(10000, gc_malloc_array_helper as *const () as i64);
        consts.insert(10001, 8_i64);
        consts.insert(10002, 7_i64);
        backend.set_constants(consts);

        let inputargs = vec![InputArg::new_int_rc(0)];
        let ops = vec![
            mk_op(OpCode::Label, &[OpRef::input_arg_int(0)], OpRef::NONE.raw()),
            mk_op_with_descr(
                OpCode::CallR,
                &[
                    OpRef::int_op(10000),
                    OpRef::int_op(10001),
                    OpRef::int_op(10002),
                    OpRef::input_arg_int(0),
                ],
                1,
                majit_ir::make_malloc_array_calldescr(),
            ),
            mk_op(
                OpCode::CheckMemoryError,
                &[OpRef::ref_op(1)],
                OpRef::NONE.raw(),
            ),
            mk_op(OpCode::Finish, &[OpRef::ref_op(1)], OpRef::NONE.raw()),
        ];

        let token = JitCellToken::new(1503);
        backend.compile_loop(&inputargs, &ops, &token).unwrap();

        let frame = backend.execute_token(&token, &[Value::Int(3)]);
        let obj = backend.get_ref_value(&frame, 0);
        assert!(!obj.is_null());
        assert_eq!(unsafe { (*header_of(obj.0)).type_id() }, 7);
        assert_eq!(unsafe { *(obj.0 as *const usize) }, 3);
    }

